WITH payload AS (SELECT $archive_payload$[{"id":"912fa4e7-0997-5c8d-a38d-979752d960bb","document_type":"judgment","category":"judicial","subcategory":"general","title":"قرض -االستدالل بالقرائن على صحة دفع املدعى عليه -الترجيح بن البينات -األصل يف املعامات بن الناس يف األحوال الطبيعية هي املعاوضات ال التبرعات -اليمن تشرع يف جانب أقوى املتداعين -صرف النظر عن الدعوى .","document_number":"34207930","case_number":"25654","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/7","year":"1434","subject":"قرض -االستدالل بالقرائن على صحة دفع املدعى عليه -الترجيح بن البينات -األصل يف املعامات بن الناس يف األحوال الطبيعية هي املعاوضات ال التبرعات -اليمن تشرع يف جانب أقوى املتداعين -صرف النظر عن الدعوى .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/5/7 :‬هـ‬\n                ‫ُ‬                 ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34207930 :‬‬\n                      ‫َر ْق ُم الدعوى‪25654 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n           ‫‪ 34279288‬تاريخه‪1434/7/25 :‬هـ‬\n\n\n\n‫قــرض ‪ -‬االســتدالل بالقرائــن علــى صحــة دفــع املدعى عليه ‪ -‬الترجيح‬\n‫بــن البينــات ‪ -‬األصــل يف املعامــات بــن النــاس يف األحــوال الطبيعيــة‬\n‫هــي املعاوضــات ال التبرعــات‪ -‬اليمــن تشــرع يف جانــب أقــوى املتداعيــن‬\n                                           ‫‪ -‬صــرف النظــر عــن الدعــوى ‪.‬‬\n\n\n\n\n‫‪ -1‬مــا قالــه القاضــي املــاوردي يف األحــكام الســلطانية‪( :‬إذا كان مــع‬\n‫املدعــى خــط املدعــى عليــه مبــا يتضمنــه الدعــوى فنظــر املظالــم فيــه‬\n‫يقتضــي ســؤال املدعــى عليــه عــن اخلــط وأن يقــال لــه‪ :‬أهــذا خطــك؟‬\n‫فــإن اعتــرف بــه يســأل بعــد اعترافــه عــن صحــة مــا تضمنــه فــإن اعتــرف‬\n‫بصحتــه صــار مقــر ًا وألــزم حكــم إقــراره وإن لــم يعتــرف بصحتــه‪...‬‬\n‫فقــد ذهــب جماعــة وهــم األكثــر وقــال املــاوردي إليــه ذهــب احملققــون‬\n‫والفقهــاء مــن والة املظالــم‪ :‬إلــى أنــه ال يجــوز للناظــر منهــم أن يحكــم‬\n‫مبجــرد اخلــط حتــى يعتــرف بصحــة مــا فيــه ألن نظــر املظالــم ال‬\n‫يبيــح مــن األحــكام مــا حظــره الشــرع ونظــر املظالــم فيــه أن يرجــع‬\n‫إلــى مــا يقــرره مــن خطــة‪ ،‬فــإن قــال‪ :‬كتبتــه ليقرضنــي ومــا أقرضنــي‪،‬‬\n‫أو ليدفــع إلـ َِّـي ثمــن مــا بعتــه ومــا دفــع إلــي‪ ،‬فهــذا ممــا يفعلــه النــاس‬\n‫أحيانـ ًا‪ ،‬ونظــر املظالــم يف مثلــه أن يســتعمل فيــه بحســب مــا يشــهد بــه‬\n                                                  ‫احلــال وتقــوى بــه األمــارة)‪.‬‬\n\n                                                                                         ‫‪100‬‬\n\f      ‫‪ -2‬مــا نــص عليــه أهــل العلــم مــن أن اليمــن تشــرع يف جانــب أقــوى‬\n                                                                   ‫املتداعيــن‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي علــى املدعــى عليــه بأنــه أقرضــه مبلغ ـ ًا مــن املــال وقــد‬\n      ‫كتــب لــه املدعــى عليــه ســند ًا بذلــك ‪ ،‬وقــد طالبــه بالســداد فلم يســدد‪،‬‬\n      ‫وقــد صــدر قــرار مــن مكتــب الفصــل بــاألوراق التجاريــة يتضمــن صرف‬\n      ‫النظــر عــن دعــوى املدعــى باملطالبــة بقيمــة الشــيك لعــدم االختصــاص‬\n      ‫ملضــي املــدة النظاميــة لتقــادم الشــيك ‪ ،‬طلــب املدعــي إلــزام املدعــى‬\n      ‫عليــه بدفــع القرضــة‪ ،‬أقــر املدعــى عليــه باســتالم املبلــغ ودفــع بأنــه مــن‬\n      ‫أجــل املضاربــة باألســهم ‪ ،‬أحضــر املدعــى عليــه شــهوده ‪ ،‬جــرى ســماع‬\n      ‫الشــهادة ورصدهــا ‪ ،‬جــرى تزكيــة الشــهود ‪ ،‬جــرى االطــاع علــى قــرار‬\n      ‫مكتــب الفصــل بــاألوراق التجاريــة ورصــد مضمونــه ‪ ،‬جــرى االطــاع‬\n      ‫علــى صــورة الشــيك ورصــد مضمونــه‪ ،‬حيــث إن اليمــن تشــرع يف جانــب‬\n      ‫أقــوى املتداعيــن جــرى طلــب اليمــن مــن املدعــى عليــه ‪ ،‬حلــف املدعــى‬\n      ‫عليــه اليمــن ‪ ،‬صــدر احلكــم بصــرف النظــر عــن دعــوى املدعــي يف‬\n      ‫مطالبتــه باملبلــغ املذكــور باعتبــاره قرض ـ ًا لعــدم ثبــوت اســتحقاق مــا‬\n      ‫يدعيــه‪ ،‬وأفهــم املدعــي بأنــه لــه املطالبــة مبــا يدعيــه باعتبــاره شــراكة‬\n      ‫وليــس قرض ـ ًا ‪ ،‬اعتــرض املدعــي علــى احلكــم ‪ ،‬صــدق احلكــم مــن‬\n                                                                ‫محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫‪101‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بالريــاض برقــم ‪ 25654‬وتاريــخ ه ـ املقيــدة باحملكمــة برقــم‬\n‫‪ 3197613‬وتاريــخ ه ـ ففــي يــوم املوافــق ه ـ افتتحــت اجللســة الســاعة‬\n‫‪ 2 :09‬وفيهــا حضــر ‪ ...‬بالبطاقــة رقــم ‪ ...‬بصفتــه وكيــا عــن ‪ ...‬مبوجــب‬\n‫الوكالــة رقــم ‪ 14715‬يف ‪1431/2/24‬ه ـ والصــادرة مــن كتابــة عــدل‬\n‫الثانيــة بالريــاض وحضــر حلضــوره ‪...‬بالبطاقــة رقــم ‪...‬وادعــى األول قائــا‬\n‫إن موكلــي قــد أقــرض املدعــى عليــه مبلــغ خمســمائة ألــف ريــال وقــد‬\n‫كتــب لــه املدعــى عليــه شــيكا مســحوبا علــى البنــك األهلــي باملبلــغ‬\n‫املذكــور برقــم ‪ 92‬يف ‪1426/9/25‬ه ـ وقــد طالبــه موكلــي بالســداد‬\n‫غيــر أنــه لــم يســدد وقــد صــدر قــرار مكتــب الفصــل بــاألوراق التجاريــة‬\n‫رقــم ‪ 1280‬يف ‪1431/4/7‬ه ـ بصــرف النظــر عــن دعــوى موكلــي‬\n‫املطالبــة بقيمــة الشــيك لعــدم االختصــاص ملضــي املــدة النظاميــة لتقــادم‬\n‫الشــيك أطلــب إلــزام املدعــى عليــه بدفــع املبلــغ املذكــور واحلكــم عليــه‬\n‫بذلــك هــذه دعــواي وبعــرض ذلــك علــى املدعــى عليــه أجــاب قائــا مــا‬\n‫ذكــره املدعــي ال صحــة لــه جملــة وتفصيــا والصحيــح أنــه أعطانــي‬\n‫مبلــغ أربعمائــة وواحــد وثمانــن ألــف للمســاهمة معــي يف األســهم وكان‬\n‫ذلــك علــى دفعــات ثــم قابلنــي بعــد ذلــك وطلــب منــي أن أكتــب له الشــيك‬\n‫املذكــور ملــدة أربعــة وعشــرين ســاعة وكتبــت لــه الشــيك املذكــور ملدة‬\n‫أربــع وعشــرين ســاعة علــى أنــا ســنلتقي ونكتــب عقــدا غيــر أن ذلــك‬\n‫لــم يتــم واال فهــو لــم يقرضنــي وقــد أقــر بذلــك بحضــور شــهود حيــث أقــر‬\n\n                                                                                    ‫‪102‬‬\n\f      ‫أنــه وبعــد اســتالمه للشــيك املذكــور أن املبلــغ املذكــور الــذي ســلمه لــي‬\n      ‫هــو شــراكة معــي يف األســهم وليــس قرضــا وكان ذلــك قبــل ســنتني‬\n      ‫تقريبــا ودليــل عــدم صحــة كالمــه أنــه لــم يقــدم الشــيك إال بعــد فــوات‬\n      ‫مدتــه وبعــرض ذلــك علــى املدعــي قــال الصحيــح مــا ذكرتــه وهــذا املبلــغ‬\n      ‫أعطــاه موكلــي للمدعــى عليــه قرضــا هكــذا أجــاب ويف يــوم الســبت‬\n      ‫املوافق ‪ 1432/5/26‬هـ افتتحت اجللســة الســاعة ‪ 10 : 30‬وفيها حضر‬\n      ‫الطرفــان وقــال املدعــى عليــه إن ا ملدعــي قــد ادعــى أنــه فقــد الشــيك ملــا‬\n      ‫طالبتــه بــه كمــا أنــه أقــر بحضــور أشــخاص أن مــا تضمنــه الشــيك‬\n      ‫ليــس قرضــا وإمنــا مســاهمة منــه معــي يف األســهم وبعــرض ذلــك علــى‬\n      ‫املدعــي قــال ال صحــة لذلــك وبطلــب البينــة مــن املدعــى عليــه علــى مــا‬\n      ‫ذكــر قــال إن لــدي شــهودا ومســتعد بإحضارهــم ورفعــت اجللســة لذلــك‬\n      ‫ويف يــوم األربعــاء املوافــق ‪1432/10/23‬ه ـ افتتحــت اجللســة الســاعة‬\n      ‫‪ 12 : 50‬وفيهــا حضــر املدعــي وكالــة وحضــر حلضــوره املدعــى عليــه‬\n      ‫وبســؤاله عــن بينتــه قــدم شــاهده ‪...‬بالبطاقــة رقــم ‪...‬واملشــار فيهــا إلــى‬\n      ‫تاريــخ امليــاد ‪1386/7/1‬ه ـ ـ وذكــر أنــه ال قرابــة بينــه وبــن املدعــي‬\n      ‫وإمنــا كان رئيســه يف العمــل أمــا املدعــى عليــه فذكــر أنــه مــن نفــس‬\n      ‫قبيلتــه ولــه معرفــة بــه وبســؤاله عمــا لديــه مــن شــهادة قــال أشــهد بــاهلل‬\n      ‫العلــي العظيــم أننــي حضــرت أنــا و‪...‬و‪...‬ملوضــوع خــاص بنــا عنــد املدعــي‬\n      ‫‪...‬وقــد جــرى حديــث بــن املدعــي أصالــة واملدعــى عليــه يف مجلــس‬\n      ‫املدعــي فقــال املدعــى عليــه للمدعــي إنــك أعطيتنــي مبلــغ خمســمائة‬\n      ‫ألــف ريــال إليداعهــا يف األســهم فقــال املدعــي بــل قــرض حســن كتبــت‬\n      ‫لــي فيــه شــيكا فطلــب املدعــى عليــه مــن املدعــي أن يحلــف أنــه قــرض‬\n      ‫فقــال املدعــي ال لــن أحلــف ولكــن يف احملكمــة ثــم قــال املدعــى عليــه‬\n\n\n‫‪103‬‬\n\f‫انــك أعطيتنــي إياهــا ألضعهــا يف األســهم وآخــر مــا شــريت يف الســيارات‬\n‫فقــال املدعــي أنــا أعطيتــك إياهــا تشــغلها يف جــن يف ســيارات أنــا أبــي‬\n‫أربــح مــا أبــي أخســر ثــم قــال إننــي أبــي حقــي بــس هــذا مــا لــدي مــن‬\n‫شــهادة كمــا قــدم شــاهده ‪ ...‬بالبطاقــة رقــم ‪...‬ذكــر يف بطاقتــه انــه‬\n‫مولــود يف ‪1397/7/1‬ه ـ وذكــر أنــه ال قرابــة لــه باملدعــي وال باملدعــى‬\n‫عليــه وإمنــا زمــاء عمــل وبســؤاله عمــا لديــه قــال أشــهد بــاهلل العلــي‬\n‫العظيــم أننــي حضــرت أنــا ومعــي ‪...‬و‪...‬إلــى منــزل ‪...‬وجــرى نقــاش بــن‬\n‫املدعــي أصالــة واملدعــى عليــه فقــال املدعــى عليــه إنــك يــا‪ ...‬أعطيتنــي‬\n‫مبلــغ أربعمائــة وثمانــن ألــف ريــال علــى دفعتــن وإنــه جــرى مقابلتــك لــي‬\n‫عنــد ســوبرماركت يخــص ‪...‬علــى أســاس أن أكتــب لــك ورقــة وكنــت‬\n‫مســتعجل فكتبــت شــيك بقيمــة خمســمائة ألــف ريــال علــى أســاس أنــك‬\n‫يــا‪ ...‬تضمــن حقــك وإال فهــي مشــاركة منــك معــي يف األســهم فأنكــر‬\n‫‪...‬أنــه أعطــى املدعــى عليــه املبلــغ املذكــور لتشــغيله يف األســهم وذكــر‬\n‫أنــه أعطــاه قرضــة فقــال علــي‪ :‬احلــف أنــه قرضــة فرفــض ‪...‬وبعــد ذلــك‬\n‫جــرى حديــث بينهمــا وكــرر املدعــى عليــه للمدعــي أنــك دخلــت معــي‬\n‫باألســهم فقــال ‪...‬أنــا مالــي شــغل تشــتري يف الســيارات أو غيرهــا أنــا‬\n‫لــي الربــح مالــي يف اخلســارة هــذا مــا لــدي مــن شــهادة وبســؤال املدعــي‬\n‫هــل لديــه مزيــد بينــه قــال إننــي ســأبحث عــن ذلــك وأطلــب مهلــة لذلــك‬\n                                                         ‫ورفعــت اجللســة لذلــك‬\n‫ويف يــوم الســبت املوافــق ‪1433/3/5‬ه ـ افتتحــت اجللســة الســاعة ‪: 05‬‬\n‫‪ 10‬وفيهــا حضــر املدعــي وكالــة ولــم يحضــر املدعــى عليــه وبســؤال‬\n‫املدعــي وكالــة عــن أصــل الشــيك والقــرار الصــادر مــن وزارة التجــارة‬\n‫قــال إننــي مســتعد بإحضــار ذلــك يف اجللســة القادمــة ويف يــوم األحــد‬\n\n\n                                                                                    ‫‪104‬‬\n\f      ‫املوافــق‪ 1433/06/22‬ه ـ افتتحــت اجللســة الســاعة ‪ 10 : 30‬وفيهــا‬\n      ‫حضــر املدعــي وكالــة ولــم يحضــر املدعــى عليــه وقــدم املدعــي صــورة‬\n      ‫طبــق األصــل مــن القــرار رقــم ‪ 1430 / 1280‬يف ‪1431 / 04 / 07‬ه ـ‬\n      ‫والصــادر مــن مكتــب الفصــل يف منازعــات األوراق التجاريــة واســم‬\n      ‫املدعــي ‪...‬وممثــل االدعــاء العــام واســم املدعــى عليــه ‪...‬والدعــوى يف قيمــة‬\n      ‫الشــيك رقــم ‪ 92‬يف ‪1426 / 09 / 25‬ه ـ واملتضمــن مبلــغ خمســمائة‬\n      ‫ألــف ريــال وقــد تضمــن القــرار أوال عــدم ســماع الدعــوى مــن ‪ ...‬ضــد‬\n      ‫املدعــى عليــه وذلــك ملضــي املــدة النظاميــة لتقــادم الشــيك ثانيــا يف احلــق‬\n      ‫العــام إيقــاع غرامــة ثالثــة آالف ريــال علــى املدعــى عليــه ونشــر اســمه‬\n      ‫تشــهيرا يف اللوحــات املعــدة بهــذا الغــرض بجميــع الغــرف التجاريــة‬\n      ‫ملــدة شــهر وقــد أرفــق صــورة منــه باملعاملــة كمــا جــرى االطــاع علــى‬\n      ‫الشــيك فوجدتــه برقــم ‪ 92‬يف ‪1426 / 09 / 25‬ه ـ مســحوب علــى البنــك‬\n      ‫األهلــي التجــاري فــرع العليــا مبلغــه خمســمائة ألــف ريــال ألمــر ‪ ...‬أشــير‬\n      ‫يف خانــة املبلــغ إلــى أنــه خمســمائة ألــف ريــال فقــط ال غيــر ســداد قرضــة‬\n      ‫حســنة وأعيــد األصــل لصاحبــه وأرفقــت صــورة منــه باملعاملــة فطلبــت‬\n      ‫مــن املدعــي وكالــة إحضــار موكلــه للحلــف فاســتعد بإحضــاره ورفعــت‬\n      ‫اجللســة لذلــك احلمــد هلل وحــده وبعــد فلــدي أنــا ‪...‬املــازم القضائــي يف‬\n      ‫املكتــب الســابع والثالثــن وبتكليــف مــن فضيلــة القائــم بعمل املكتب‬\n      ‫الشــيخ ‪...‬القاضــي يف احملكمــة العامــة بالريــاض ففــي يــوم األحــد‬\n      ‫املوافــق‪ 1434/02/03‬ه ـ افتتحــت اجللســة الســاعة احلاديــة عشــرة وفيها‬\n      ‫حضــر ‪ ......‬ســعودي بالبطاقــة رقــم ‪...‬وحضــر حلضــوره املدعــى عليــه ‪...‬‬\n      ‫وقــال األخيــر إننــي أطلــب مهلــة إلحضــار مزيــد بينــة فأجيــب لطلبــه ويف‬\n      ‫يوم األربعاء املوافق‪ 1434/03/04‬هـ افتتحت اجللســة الســاعة التاســعة‬\n\n\n‫‪105‬‬\n\f‫والنصــف وفيهــا حضــر الطرفــان وقــدم املدعى عليه ‪...‬ســعودي بالبطاقة‬\n‫رقــم ‪...‬وقــد أشــير يف بطاقتــه إلــى أن ميــاده يف ‪ 1397/10/13‬وبســؤاله‬\n‫عــن عالقتــه بالطرفــن قــال ليــس لــي قرابــة بأحدهمــا وبســؤاله عــن‬\n‫شــهادته أشــهد بــاهلل العلــي العظيــم أن املدعــي أرســلني للمدعــى عليــه‬\n‫وقــال لــي خلصنــي مــن الرجــال الــذي هــو املدعــى عليــه مــن املبلــغ الــذي‬\n‫أطلبــه بــه وقــدره خمســمائة ألــف ريــال فذهبــت للمدعــى عليــه فقــال‬\n‫لــي املــال الــذي عنــدي يف األســهم واألســهم يف احملفظــة ولــدي مــا يثبــت‬\n‫ذلــك واملدعــي يعلــم بهــذا فذهبــت للمدعــي فقلــت لــه يــا ‪ ...‬أنــت تقــول‬\n‫إنهــا قرضــة حســنة ولكــن املدعــى عليــه يقــول إن مالــك يف األســهم‬\n‫واألســهم يف محفظتــه واألســهم ال زالــت موجــودة وأنــك يــا ‪ ...‬تعلــم بذلــك‬\n‫كلــه وأنــه يشــغلها لــك يف األســهم وعلــى هــذا فســآتي مبحاســب وندقــق‬\n‫يف الربــح واخلســارة فقــال لــي املدعــي تصــرف وخلصنــي منــه والصلــح‬\n‫الــذي تأتــي بــه لــن أعارضــك فيــه ثــم قــال لــي املدعــى عليــه لــن أعارضــك‬\n‫فأوراقــي موجــودة ومحفظتــي موجــودة فلمــا ذهبــت للمدعــي لتحديــد‬\n‫املوعــد لالجتمــاع بــن الطرفــن قــال لــي أنــا ال أعــرف أســهم وال محفظــة‬\n‫بــل هــي قرضــة حســنة فاتصلــت باملدعــى عليــه فقلــت لــه ذلــك فقــال إذا‬\n‫كنــا علــى الطريقــة األولــى التــي حددتهــا لنــا مــن االجتمــاع وإحضــار‬\n‫محاســب ونحــو ذلــك فأنــا معــك وإذا كان يدعــي أنهــا قــرض حســن‬\n‫فليذهــب للمحكمــة وال أدري عــن ســبب إعطــاء املبلــغ أول مــرة بــن‬\n‫الطرفــن هكــذا شــهد وبعــرض ذلــك علــى املدعــي قــال أنــا أقرضتــه‬\n‫قرضــة حســنة وال عالقــة لــي بعملــه باملبلــغ الــذي أقرضتــه إيــاه وقــال‬\n‫املدعــى عليــه لــدي مزيــد بينــة لديهــا مزيــد اطــاع علــى مــا حــدث بيننــا‬\n                                         ‫فأجيــب لطلبــه ورفعــت اجللســة لذلــك‬\n\n\n                                                                                       ‫‪106‬‬\n\f      ‫ويف يــوم الســبت املوافــق‪ 1434/04/20‬ه ـ افتتحــت اجللســة الســاعة‬\n      ‫احلاديــة عشــرة والنصــف وفيهــا حضــر الطرفــان وقــدم املدعــى عليــه‬\n      ‫‪...‬ســعودي بالبطاقــة رقــم ‪...‬وقــد أشــير يف بطاقتــه إلــى أن ميــاده يف‬\n      ‫‪ 1393/3/30‬وبســؤاله عــن قرابتــه بالطرفــن قــال ال قرابــة لــي بأحــد‬\n      ‫وبســؤاله عــن شــهادته قــال أشــهد بــاهلل العلــي العظيــم أننــي كنــت يف‬\n      ‫بيــت املدعــي بحضــور املدعــى عليــه وقال املدعي للمدعى عليه إن الناس‬\n      ‫عوضت اخلســارة يف شــركة ‪ ...‬و‪...‬و‪ ...‬وأنت لم تعوض قال املدعى عليه‬\n      ‫أنــا لــم أدخــل يف هــذه الشــركات وال أدري مــا املــراد باخلســارة وال ســبب‬\n      ‫ســؤال املدعــي للمدعــى عليــه عــن ذلــك وقــد ســمعت أن بــن املدعــي‬\n      ‫واملدعــى عليــه تعامــل مالــي ولكــن ال أدري مــا طبيعتــه وال أعــرف‬\n      ‫ماهيتــه وذلــك ألننــا كنــا يف إدارة واحــدة والــكالم يــدور بيننــا هكــذا‬\n      ‫شــهد وبســؤال املدعــى عليــه هــل لديــه مزيــد بينــة قــال ليــس لــدي مزيــد‬\n      ‫بينــة وأكتفــي مبــا قدمــت ويف يــوم األربعــاء املوافــق‪ 1434/05/01‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة العاشــرة والربــع وفيهــا حضــر الطرفــان وقــال‬\n      ‫الطرفــان إن محــاوالت اإلصــاح بيننــا لــم جتــد وقــال املدعــى عليــه إن‬\n      ‫املبلــغ كان يف عــام ‪ 1426‬يف وقــت اشــتغال النــاس باألســهم وبعــرض‬\n      ‫ذلــك علــى املدعــي قــال صحيــح أن املبلــغ كان يف عــام ‪ 1426‬وال عالقــة‬\n      ‫لــي مبــا ذكــره وقــال املدعــى عليــه إننــي مســتعد باحللــف مــع شــهودي‬\n      ‫وطلبــت مــن املدعــى عليــه مزكيــن لشــهوده فوعــد بإحضارهــم ورفعــت‬\n      ‫اجللســة لذلــك ويف يــوم الســبت املوافــق‪ 1434/05/04‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة العاشــرة والنصــف وفيهــا حضــر الطرفــان وبســؤال‬\n      ‫املدعــي إن كان املبلــغ املذكــور قرضــا فمــا هــي آخــر مهلــة للســداد‬\n      ‫قــال لــم أعطــه موعــدا محــددا للســداد وإمنــا هــو وقــت مفتــوح متــى مــا‬\n\n\n‫‪107‬‬\n\f‫رغبــت فيــه طلبتــه منــه وبســؤاله ملــاذا لــم يصــرف الشــيك فــور اســتالمه‬\n‫قــال إننــي لــم أكــن يف حاجتــه وكنــت مشــغوال ذلــك الوقــت وقــد‬\n‫ذهبــت للبنــك بعــد ثمانيــة أو تســعة أشــهر فقالــوا إن الشــيك ليــس لــه‬\n‫رصيــد وتركتــه لثقتــي بصاحبــي ومراعــاة لــه لعــل ظروفــه لــم تســمح لــه‬\n‫وأمــا رفعــي للدعــوى يف الغرفــة التجاريــة يف ‪ 1431/2/29‬فهــذه املــدة‬\n‫ألجــل محاولــة اإلصــاح بيننــا وبســؤال املدعــى عليــه ملــاذا كتــب قرضــة‬\n‫حســنة يف الشــيك قــال إننــي كتبــت الشــيك لطلبــه حيــث كان املتفــق‬\n‫عليــه أن نكتــب عقــدا بعــد يومــن وللثقــة بيننــا والســتعجالي وعــدم‬\n‫كفايــة الشــيك لكتابــة التفصيــات وحيــث وعدنــي املدعــي بإعــادة‬\n‫الشــيك لــي بعــد كتابــة العقــد بيننــا بعــد يومــن لتفصيــل العالقــة بيننــا‬\n‫والصحيــح أن املبالــغ التــي وصلتنــي منــه أربعمائــة وثمانيــة وثمانــون ألــف‬\n‫ريــال وســبب كتابتــي ملبلــغ خمســمائة ألــف هــو أن املدعــي كان يريــد‬\n‫بيــع أســهم لــه وكانــت قيمتهــا مائــة ألــف ولكــن نزلــت قيمتهــا إلــى‬\n‫ثمانيــة وثمانــن ألــف ريــال وقــت البيــع وقــد كتبــت الشــيك قبــل ذلــك‬\n‫للثقــة بيننــا فســلمني مبلــغ ثمانيــة وثمانــن ألــف ريــال وأمــا دعــواه أن‬\n‫حســابي ال يغطــي أثنــاء فعاليــة الشــيك فغيــر صحيــح ولــدي كشــف‬\n‫حســاب يثبــت تغطيــة حســابي للشــيك خــال مــدة فعاليــة الشــيك وقــال‬\n‫املدعــي إن لــدي شــاهدا أريــد ســماع شــهادته وقــدم ‪...‬ســعودي بالبطاقــة‬\n‫رقــم ‪...‬وقــال ال قرابــة لــي بأحــد الطرفــن وبســؤاله عمــا لديــه قــال إننــي‬\n‫راعــي مكتــب عقــار وقــد عــرض علــي املدعــى عليــه قطعتــي أرض‬\n‫لبيــع هــذا مــا لــدي وبســؤال املدعــى عليــه عــن املزكــن قــدم كال مــن‬\n‫‪...‬ســعودي بالبطاقــة رقــم ‪...‬و‪...‬ســعودي بالبطاقــة رقــم ‪...‬وشــهدا قائلــن‬\n‫إن ‪...‬و‪...‬و‪ ...‬و‪...‬ثقــات عــدول مرضيــون لنــا وعلينــا ثــم اســتعد املدعــى‬\n\n\n                                                                                      ‫‪108‬‬\n\f      ‫عليــه باحللــف ثــم حلــف قائــا واهلل العلــي العظيــم الــذي ال إلــه غيــره وال‬\n      ‫رب ســواه الغالــب الطالــب املهلــك املــدرك إن املبلــغ الــذي اســتلمته مــن‬\n      ‫املدعــي وهــو أربعمائــة وثمانيــة وثمانــون ألــف ريــال هــو شــراكة مــن‬\n                        ‫املدعــي معــي وليــس قرضــا منــه لــي واهلل العلــي العظيــم‬\n      ‫وعليــه وملــا تقــدم مــن الدعــوى واإلجابــة وملــا دلــت عليــه البينــة املعدلــة‬\n      ‫شــرعا يف شــهادة كل مــن األول ‪ ...‬والثانــي ‪...‬مــن أن املدعــي قــال‬\n      ‫للمدعــى عليــه إننــي أريــد الربــح وال أريــد اخلســارة ومعلــوم أن الربــح‬\n      ‫واخلســارة ال تأتــي إال مــن املعاوضــات أو املشــاركات ال مــن التبرعــات‬\n      ‫كالقــرض‪ ،‬وإلقــرار املدعــي علــى مــا قالــه الشــاهد الثالــث ‪ .....‬عنــد‬\n      ‫محاولتــه اإلصــاح بــن الطرفــن عندمــا قــال للمدعــي إنــه ســيأتي‬\n      ‫مبحاســب لتدقيــق حســاب الربــح واخلســارة يف األســهم فرضــي املدعــي‬\n      ‫بذلــك وصــرح بعــدم معارضتــه ملثــل هــذا الصلــح ومــن املعلــوم أن الصلــح‬\n      ‫يف القــرض إمنــا يكــون يف األجــل والتقســيط وال يــرد فيــه محاولــة‬\n      ‫اإلصــاح عبــر احملاســب وملــا دلــت عليــه شــهادة الرابــع من ســؤال املدعي‬\n      ‫للمدعــى عليــه عــن ســبب عــدم تعويضــه للخســارة يف شــركات أســهم‬\n      ‫عددهــا كمــا فعــل النــاس ممــا يــدل علــى حــرص املدعــي علــى نفــي‬\n      ‫خســارة مالــه وتعويضهــا وهــو مــا يتطابــق مــع شــهادة األول والثانــي ويــدل‬\n      ‫علــى علــم املدعــي بكــون مالــه الــذي ســلمه للمدعــي ليــس قرضــا وإمنــا‬\n      ‫مشــاركة ويؤكــد هــذا وقوعهــا يف عــام ‪ 1426‬كمــا تصــادق عليــه‬\n      ‫الطرفــان حيــث ازداد اشــتغال النــاس باألســهم والدخــول يف هــذا املجــال‬\n      ‫ولكــون الشــيك املذكــور ممــا يغلــب بــن النــاس اتخــاذه لتوثيــق احلقــوق‬\n      ‫وطمأنــة الشــركاء ويؤكــد ذلــك أن املدعــي لــم يقــم بصرفــه ملــدة طويلة‬\n      ‫ولــو كان قرضــا كمــا يدعيــه لــكان ذلــك اســتردادا حلقــه ال مينعــه أحد‬\n\n\n‫‪109‬‬\n\f‫مــن اســتيفاءه يف وقتــه ولكــون أصــل املعامــات بــن النــاس يف األحــوال‬\n‫الطبيعيــة هــي املعاوضــات ال التبرعــات وملــا قالــه القاضــي املــاوردي ‪...‬يف‬\n‫األحــكام الســلطانية‪( :‬إذا كان مــع املدعــي خــط املدعــى عليــه مبــا‬\n‫يتضمنــه الدعــوى‪ ،‬فنظــر املظالــم فيــه يقتضــي ســؤال املدعــى عليــه‬\n‫عــن اخلــط‪ ،‬وأن يقــال لــه‪ :‬أهــذا خطــك؟ فــإن اعتــرف بــه‪ ،‬يســأله بعــد‬\n‫اعترافــه عــن صحــة مــا تضمنــه‪ ،‬فــإن اعتــرف بصحتــه صــار مقــرا‬\n‫وألــزم حكــم إقــراره وإن لــم يعتــرف بصحتــه ‪ ...‬فقــد ذهــب جماعــة وهــم‬\n‫األكثــر وقــال املــاوردي إليــه ذهــب احملققــون والفقهــاء مــن والة املظالــم‪:‬‬\n‫إلــى أنــه ال يجــوز للناظــر منهــم‪ ،‬أن يحكــم مبجــرد اخلــط‪ ،‬حتــى يعتــرف‬\n‫بصحــة مــا فيــه‪ ،‬ألن نظــر املظالــم ال يبيــح مــن األحــكام مــا حظــره‬\n‫الشــرع ونظــر املظالــم فيــه‪ :‬أن يرجــع إلــى مــا يذكــره مــن خطــه‪ ،‬فــإن‬\n‫قــال‪ :‬كتبتــه ليقرضنــي ومــا أقرضنــي‪ ،‬أو ليدفــع إلــي ثمــن مــا بعتــه‪،‬‬\n‫ومــا دفــع إلــي‪ ،‬فهــذا ممــا يفعلــه النــاس أحيانــا‪ ،‬ونظــر املظالــم يف مثلــه‪:‬‬\n‫أن يســتعمل فيــه بحســب مــا يشــهد بــه احلــال‪ ،‬وتقــوى بــه األمــارة ) انتهــى‬\n‫وملــا دلــت عليــه شــهادة الشــهود الســابق ذكرهــا وملــا نــص عليــه أهــل‬\n‫العلــم مــن أن اليمــن يف جانــب أقــوى املتداعيــن وحللــف املدعــى عليــه‬\n‫اليمــن الشــرعية املطلوبــة منــه وملــا تقــدم جميعــه فقــد صرفــت النظــر‬\n‫عــن دعــوى املدعــي يف مطالبتــه باملبلــغ املذكــور باعتبــاره قرضــا لعــدم‬\n‫ثبــوت اســتحقاق مــا يدعيــه وبذلــك حكمــت وأفهمــت املدعــي أن لــه‬\n‫املطالبــة مبــا يدعيــه مــن حــق باعتبــاره شــراكة وليــس قرضــا لعــدم‬\n‫ثبوتــه وبعــرض احلكــم علــى الطرفــن قــرر املدعــى عليــه القناعــة وقــرر‬\n‫املدعــي عــدم القناعــة وطلــب االســتئناف بــدون الئحــة فأجبتــه لطلبــه‬\n‫وأمــرت بتنظيــم الصــك الــازم وتســجيله ورفعــه حملكمــة االســتئناف‬\n\n\n                                                                                        ‫‪110‬‬\n\f      ‫لتدقيقــه وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                   ‫وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/05/04‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم الثالثــاء املوافــق‪ 1434/07/11‬ه ـ‬\n      ‫افتتحت اجللســة الســاعة الثانية عشــرة وفيها حضر ‪...‬ســعودي بالبطاقة‬\n      ‫رقــم ‪...‬بصفتــه وكيــا عــن ‪...‬مبوجــب الوكالــة الصــادرة مــن كتابــة‬\n      ‫العــدل الثانيــة بجنــوب الريــاض برقــم ‪ 34838881‬يف ‪1434/7/1‬‬\n      ‫واملخولــة لــه حــق املرافعــة واملدافعــة واإلقــرار واإلنــكار والصلــح‬\n      ‫والتنــازل واإلبــراء وطلــب اليمــن ورده واالمتنــاع عنــه وقبــول األحــكام‬\n      ‫ونفيهــا ولــم يحضــر املدعــى عليــه وقــد وردتنــا املعاملــة مــن محكمــة‬\n      ‫االســتئناف بالقــرار رقــم ‪ 34235397‬يف ‪ 1434/6/10‬واملتضمــن وجــد‬\n      ‫أوال أن فضيلتــه لــم يــدون مضمــون وكالــة املدعــي وهــل تخولــه الســير‬\n      ‫يف الدعــوى واإلقــرار ثانيــا أن فضيلتــه صــرف النظــر عــن دعــوى املدعــي‬\n      ‫يف مطالبتــه باملبلــغ املذكــور كونــه قرضــا لعــدم ثبــوت اســتحقاق مــا‬\n      ‫يدعيــه وبــه حكــم ولــم يذكــر فضيلتــه مــا ثبــت لديــه بهــذا اخلصــوص‬\n      ‫بعــد بــذل املدعــى عليــه اليمــن والبينــة التــي أحضرهــا وال بــد مــن‬\n      ‫إيضــاح مــا ثبــت لــدى فضيلتــه يف ذمــة املدعــى عليــه واحلكــم بــه ومــن‬\n      ‫ثــم عرضــه علــى األطــراف فمالحظــة مــا ذكــر وإكمــال مــا يلــزم‬\n      ‫وعليــه فقــد جــرى االطــاع علــى وكالــة ‪...‬عــن ‪...‬الصــادرة مــن كتابــة‬\n      ‫العــدل الثانيــة بالريــاض برقــم ‪ 14715‬يف ‪ 1431/2/24‬واملخولــة لــه حــق‬\n      ‫املرافعــة واملدافعــة واإلقــرار واإلنــكار وجــرى عرضهــا علــى املدعــي‬\n      ‫وكالــة ‪...‬فأجــاب قائــا إن موكلــي وكل ‪...‬مبوجــب هــذه الوكالــة‬\n      ‫املشــار إليهــا وهــي تخولــه حــق املرافعــة واملدافعــة واإلقــرار هكــذا أقــر‬\n      ‫ومــا يتعلــق بثانيــا فــإن اإلثبــات ال بــد أن يكــون مســبوقا بطلــب وليــس‬\n\n\n‫‪111‬‬\n\f‫مــن حــق الناظــر أن يثبــت مــا لــم يطلــب اخلصمــان إثباتــه كمــا أنــه ال‬\n‫يصــح إلــزام املدعــى عليــه بتصفيــة الشــراكة وتســليم املســتحق شــرعا‬\n‫للمدعــي دون طلــب فكذلــك األمــر يف إثبــات صفــة املــال وطلــب املدعــي‬\n‫محصــور يف إثبــات أن املــال قــرض وطلــب املدعــى عليــه محصــور يف نفــي‬\n‫ذلــك وإثبــات أمــر آخــر هــو دعــوى مســتقلة جــرى إفهــام املدعــي أن لــه‬\n‫إقامــة مطالبتــه بهــذا املــال مــن غيــر أن تكــون املطالبــة بــه علــى صفــة‬\n‫القــرض وعليــه فلــم يظهــر لــي ســوى مــا حكمــت وأمــرت بإعــادة املعاملة‬\n‫حملكمــة االســتئناف لتدقيــق احلكــم وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل على‬\n   ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/07/11‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ‪ ...‬فقــد اطلعنــا نحــن قضــاة الدائــرة األولــى‬\n‫لتدقيــق القضايــا احلقوقيــة مبحكمــة االســتئناف مبنطقــة الريــاض‬\n‫علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة بالريــاض‬\n‫برقــم ‪ 341327775‬وتاريــخ ‪ 1434/7/19‬ه ـ املرفــق بهــا الصــك‬\n‫الصــادر مــن فضيلــة املــازم القضائــي باحملكمــة الشــيخ ‪ ...‬املســجل‬\n‫برقــم ‪ 34207930‬وتاريــخ ‪1434/5/7‬ه ـ اخلــاص بدعــوى ‪ ...‬بالوكالــة‬\n‫عــن ‪ ...‬ضـ ـ ــد ‪ ...‬بشــأن مطالبــة ماليــة علــى النحــو املوضــح بالصــك‬\n‫واملتضمــن حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه‪ ،‬وباالطــاع‬\n‫ـاء علــى قــرار الدائــرة رقــم ‪34235397‬‬   ‫علــى مــا أجــاب بــه فضيلتــه بنـ ً‬\n‫وتاريــخ ‪1434/6/10‬ه ـ لــم يظهــر لألكثريــة مــا يوجــب النقــض بعــد‬\n‫اإلجــراء األخيــر‪ .‬واهلل املوفــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                                              ‫وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                    ‫‪112‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"8772d0b1-3c0f-5928-9c22-98c49da1913e","source_page_start":100,"source_page_end":112,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"6644eff817e516e0727ab1bbc9ed1c20ac1a14a6623e20038acf2cd826404840","normalized_text_hash":"cf07702a59fe72dd462d223c6310bd35658a14d63220439ee294eb047af0e9a6","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v4-p100-34207930"},{"id":"f47a0929-307b-5a66-8d11-3f99ac525aed","document_type":"judgment","category":"judicial","subcategory":"general","title":"قرض -تخلف املدعى عليه رغم تبلغه لشخصه -القضاء بالشاهد العدل مع اليمن -من ادعى على غائب أو مستتر وله بينه سمعت وحكم له مع ميينه -إلزام املدعى عليه بدفع مبلغ القرض .","document_number":"34293616","case_number":"32175321","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/8/10","year":"1434","subject":"قرض -تخلف املدعى عليه رغم تبلغه لشخصه -القضاء بالشاهد العدل مع اليمن -من ادعى على غائب أو مستتر وله بينه سمعت وحكم له مع ميينه -إلزام املدعى عليه بدفع مبلغ القرض .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/8/10 :‬هـ‬\n                       ‫ُ‬                 ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪34293616 :‬‬\n                          ‫َر ْق ُم الدعوى‪32175321 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                 ‫‪ 34353389‬تاريخه‪1434/11/6 :‬هـ‬\n\n\n\n      ‫قــرض ‪ -‬تخلــف املدعــى عليــه رغــم تبلغــه لشــخصه ‪ -‬القضــاء بالشــاهد‬\n      ‫العــدل مــع اليمــن ‪ -‬مــن ادعــى علــى غائــب أو مســتتر ولــه بينــه ســمعت‬\n            ‫وحكــم لــه مــع ميينــه ‪ -‬إلــزام املدعــى عليــه بدفــع مبلــغ القــرض ‪.‬‬\n\n\n\n\n      ‫‪ -1‬قضــاء النبــي صلــى اهلل عليــه وســلم باليمــن مــع الشــاهد كمــا يف‬\n                              ‫حديــث ابــن عبــاس رضــي اهلل عنهمــا عنــد مســلم ‪.‬‬\n      ‫‪ -2‬قــال املجــد أبــو البــركات رحمــه اهلل يف احملــرر‪( :‬ومــن ادعــى علــى‬\n      ‫غائــب أو مســتتر يف البلــد أو ميــت أو صبــي أو مجنــون ولــه بينــه ســمعت‬\n                        ‫وحكــم لــه بهــا ويســتحلفه احلاكــم علــى بقــاء حقــه )‬\n                                      ‫‪ -3‬املادة (‪ )55‬من نظام املرافعات الشرعية‬\n\n\n\n\n      ‫حضــر املدعــى ولــم يحضــر املدعــى عليــه رغــم تبلغــه لشــخصه ‪ ،‬قــرر‬\n      ‫القاضــي الســير يف نظــر الدعــوى بنــاء علــى املــادة (‪ )55‬مــن نظــام‬\n      ‫املرافعــات الشــرعية ‪ ،‬بســؤال املدعــى عــن دعــواه قــال إن لــي بذمــة‬\n      ‫املدعــى عليــه مبلغ ـ ًا قــدره خمســون ألــف ريــال قرض ـ ًا حســن ًا ‪ ،‬طلــب‬\n      ‫إلــزام املدعــى عليــه بســدادها ‪ ،‬احضــر شــاهدا فشــهد علــى صحــه‬\n\n‫‪113‬‬\n\f‫دعــواه ‪،‬جــرى تعديــل الشــاهد ‪ ،‬حلــف املدعــى اليمــن تكملــة لبينتــه ‪،‬‬\n‫صــدر احلكــم بإلــزام املدعــى عليــه بدفــع املبلــغ املدعــى بــه للمدعــي ‪،‬‬\n‫يعــد هــذا احلكــم حضوريــا ‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة‬\n‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة العامــة مبحافظــة جدة‪/‬املســاعد برقــم ‪ 32175321‬وتاريــخ‬\n‫‪ 1432/05/15‬ه ـ املقيــدة باحملكمــة برقــم ‪ 32549551‬وتاريــخ‬\n‫‪ 1432/05/15‬ه ـ حضــر املدعــي ‪ ...‬ســعودي اجلنســية بالســجل املدنــي‬\n‫رقــم ‪...‬ولــم يحضــر املدعــى عليــه وقــد وردنــا خطــاب قائــد كتيبــة‬\n‫الشــرطة العســكرية الثانيــة برقــم ‪ 2192‬يف ‪1434/5/7‬ه ـ واملتضمــن‬\n‫تبليــغ املدعــى عليــه لشــخصه وتوقيعــه علــى ورقــة التبليــغ لــذا وبنــاء علــى‬\n‫املــادة اخلامســة واخلمســن مــن نظــام املرافعــات الشــرعية تقــرر الســير‬\n‫يف هــذه القضيــة غيابيــا وبســؤال املدعــي عــن دعــواه ادعــى قائــا إن‬\n‫لــي بذمــة املدعــى عليــه الغائــب مبلــغ وقــدره خمســون ألــف ريــال قرضــة‬\n‫حســنة أطلــب إلــزام املدعــى عليــه بســدادها هــذه دعــواي وبســؤاله البينــة‬\n‫قــال اطلــب اإلمهــال فأجبتــه لطلبــه عليــه فقــد تأجلت اجللســة ويف اجللســة‬\n‫التاليــة حضــر املدعــي أصالــة املثبتــة هويتــه ســابقا ولــم يحضــر املدعــى‬\n‫عليــه وبســؤال املدعــي عمــا اســتمهل مــن أجلــه أحضــر للشــهادة وأدائهــا‬\n‫‪ ...‬ســعودي اجلنســية بالســجل املدنــي رقــم ‪...‬مــن مواليــد ‪1386/3/19‬ه ـ‬\n‫ويعمــل يف املؤسســة العامــة لتحليــة امليــاه ويســكن حــي الصفــا يف جــدة‬\n‫وبســؤاله عــن عالقتــه بالطرفــن قــال املدعــي صديقــي وال تربطنــي‬\n                                                                                       ‫‪114‬‬\n\f      ‫باملدعــى عليــه عالقــة ولــدى استشــهاده شــهد بقولــه أشــهد بــاهلل أن‬\n      ‫املدعــي قــام بإقــراض املدعــى عليــه مبلــغ وقــدره خمســون ألــف ريــال‬\n      ‫هكــذا شــهد وبســؤال املدعــي هــل لديــك مزيــد بينــة قــال ال عليــه فقــد‬\n      ‫طلبــت منــه مزكيــن لشــاهده فأحضــر كال مــن ‪ ...‬ســعودي اجلنســية‬\n      ‫بالســجل املدنــي رقــم ‪...‬و‪...‬ســعودي اجلنســية بالســجل املدنــي رقــم‬\n      ‫‪...‬ولــدى استشــهادهما شــهدا بعدالــة وثقــة الشــاهد وأنــه مقبــول الشــهادة‬\n      ‫عليــه فقــد أفهمــت املدعــي بــأن عليــه اليمــن الشــرعية املكملــة لبينتــه‬\n      ‫فاســتعد بذلــك وأذنــت لــه ببذلهــا فحلــف قائــا واهلل العظيــم الــذي ال إله‬\n      ‫إال هــو عالــم الغيــب والشــهادة أننــي قمــت بإقــراض املدعــى عليــه الغائــب‬\n      ‫مبلــغ وقــدره خمســون ألــف ريــال وأن حقــي بــاق يف ذمتــه لــم أبرئــه منــه‬\n      ‫هكــذا حلــف فبنــاء علــى مــا تقــدم مــن الدعــوى وملــا أحضــره املدعــي‬\n      ‫مــن شــاهد معــدل ولقضــاء النبــي صلــى اهلل عليــه وســلم باليمــن مــع‬\n      ‫الشــاهد مــن حديــث ابــن عبــاس رضــي اهلل عنهمــا يف صحيــح مســلم‬\n      ‫وملــا ذكــره املجــد أبــو البــركات رحمــه اهلل يف محــرره بقولــه (ومــن‬\n      ‫ادعــى علــى غائــب أو مســتتر يف البلــد أو ميــت أو صبــي أو مجنــون ولــه‬\n      ‫بينــة ســمعت وحكــم لــه بهــا ويســتحلفه احلاكــم علــى بقــاء حقــه) أه ـ‬\n      ‫وألداء املدعــي لليمــن التــي طلبــت منــه وبنــاء علــى الالئحــة األولــى مــن‬\n      ‫املــادة اخلامســة واخلمســن مــن نظــام املرافعــات الشــرعية ولتبلــغ املدعــى‬\n      ‫عليهــا لشــخصه لــذا وجلميــع مــا تقــدم فقــد ثبــت لــدي يف ذمــة املدعــى‬\n      ‫عليــه الغائــب عــن مجلــس احلكــم ‪...‬للمدعــي ‪...‬مبلــغ خمســن ألــف‬\n      ‫ريـ‪ 50000‬ــال وألزمتــه بســداده حــا ًال وبــه حكمــت ويعــد احلكــم يف حــق‬\n      ‫املدعــى عليــه حضوريـ ًا وســيتم بعــث صــورة مــن إعــام احلكــم للمدعــى‬\n      ‫عليــه لتقــدمي اعتراضــه عليــه خــال ثالثــن يوم ـ ًا مــن تاريــخ اســتالمه‬\n\n\n‫‪115‬‬\n\f‫لــه وإذا لــم يتــم تقــدمي اعتراضــه خــال املــدة املذكــورة فيســقط حقــه‬\n‫يف االعتــراض ويكتســب احلكــم القطعيــة وســيعامل وفــق مــا نصــت‬\n‫عليــه املــادة السادســة والســبعني بعــد املائــة واملــادة الثامنــة والســبعني‬\n‫بعــد املائــة مــن نظــام املرافعــات الشــرعية وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/08/10‬هـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ففــي‬\n‫يــوم اإلثنــن املوافــق‪ 1434/12/02‬ه ـ افتتحــت اجللســة الســاعة ‪11 : 15‬‬\n‫وقــد عــادت املعاملــة مــن محكمــة االســتئناف مبكــة املكرمــة الدائــرة‬\n‫احلقوقيــة الرابعــة مبوجــب برقــم ‪ 32549551‬يف ‪1434/11/23‬ه ـ‬\n‫وبرفقهــا القــرار رقــم ‪ 34353389‬وتاريــخ ‪ 1434/11/6‬ه ـ املتضمــن‬\n‫(بدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة تقــررت املوافقة‬\n‫علــى احلكــم قاضيــا اســتئناف ‪...‬ختــم وتوقيــع و ‪...‬ختــم وتوقيــع و رئيــس‬\n‫الدائــرة ‪ ...‬ختــم وتوقيــع ) وبذلــك يكــون احلكــم اكتســب القطعيــة‪.‬‬\n‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                         ‫وســلم ‪ .‬حــرر يف ‪ 1434/12/02‬ه ـ ‪.‬‬\n‫احلمــد هلل ‪ ،‬والصــاة والســام علــى رســول اهلل ‪ ،‬وبعــد ‪.:‬فقــد‬\n‫جــرى اطالعنــا نحــن رئيــس وعضــوي الدائــرة احلقوقيــة الرابعــة يف‬\n‫محكمــة االســتئناف مبنطقــة مكــة املكرمــة علــى الصــك الصــادر‬\n‫مــن فضيلــة الشــيخ‪ ... /‬القاضــي باحملكمــة العامــة بجــدة واملســجل‬\n‫بعــدد ‪34293616‬وتاريــخ ‪1434/8/10‬ه ـ املتضمــن دعــوى ‪ ...‬ضــد‬\n‫‪ ...‬واحملكــوم فيــه مبــا دون باطنــة وبدراســة الصــك وصــورة ضبطــه‬\n‫والالئحــة االعتراضيــة تقــررت املوافقــة علــى احلكــم‪ .‬وصلــى اهلل علــى‬\n                                  ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n                                                                                     ‫‪116‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"8772d0b1-3c0f-5928-9c22-98c49da1913e","source_page_start":113,"source_page_end":116,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"f140947f1cfd21058420a7931d488574dcf287459f9cc307fbbc925d44dd3015","normalized_text_hash":"7ae29cf7b3cf54a9457fa2477a381fa74c622b7f71fe7af74b867cef7aa74f61","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v4-p113-34293616"},{"id":"d8e9592c-ad11-53f6-afb6-2947d2d3593f","document_type":"judgment","category":"judicial","subcategory":"general","title":"قرض -من أنكر احلق ثم ملا قامت البينة ادعى قضاء أو إبراء سابقا إلنكاره لم يسمع وإن أتى ببينة -االستدالل على صحة الدعوى بالقرائن -احلكم بالقرائن -احلكم بإلزام املدعى عليه بدفع مبلغ القرض.","document_number":"34330175","case_number":"32601199","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/10/14","year":"1434","subject":"قرض -من أنكر احلق ثم ملا قامت البينة ادعى قضاء أو إبراء سابقا إلنكاره لم يسمع وإن أتى ببينة -االستدالل على صحة الدعوى بالقرائن -احلكم بالقرائن -احلكم بإلزام املدعى عليه بدفع مبلغ القرض.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/10/14 :‬هـ‬\n                        ‫ُ‬                ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪34330175 :‬‬\n                          ‫َر ْق ُم الدعوى‪32601199 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                 ‫‪ 35111495‬تاريخه‪1435/1/10 :‬هـ‬\n\n\n\n       ‫قــرض ‪ -‬مــن أنكــر احلــق ثــم ملــا قامــت البينــة ادعــى قضــاء أو إبــراء‬\n       ‫ســابقا إلنــكاره لــم يســمع وإن أتــى ببينــة ‪ -‬االســتدالل علــى صحــة‬\n       ‫الدعــوى بالقرائــن ‪ -‬احلكــم بالقرائــن ‪ -‬احلكــم بإلــزام املدعــى عليــه‬\n                                                              ‫بدفــع مبلــغ القــرض‪.‬‬\n\n\n\n\n                                          ‫‪ -1‬قاعدة ‪ :‬نسبة احلادث ألقرب أوقاته ‪.‬‬\n       ‫‪ -2‬قــال يف اإلقنــاع وشــرحه الكشــاف (‪ ( : )341/6‬فأمــا إن انكــره ثــم ثبت‬\n       ‫فادعــى قضــاء أو إبــراء ســابقا إلنــكاره لــم يســمع منــه وإن اتــى ببينــة‬\n       ‫نصـ ًا ‪ ،‬فلــو ادعــى عليــة ألفــا مــن قــرض فقــال ‪ :‬مــا اقترضــت منــه شــيئا‬\n       ‫أو مــن ثمــن مبيــع فقــال ‪ :‬مــا ابتعــت منــه شــيئا ثــم ثبــت انــه اقتــرض أو‬\n       ‫اشــتري ببينــة أو اقــرر فقــال ‪ :‬قضيتــه مــن قبــل هــذا الوقــت أو أبرأنــي‬\n       ‫مــن قبــل هــذا الوقــت لــم يقبــل منــه ولــو قــام بــه بينــة ألن القضــاء أو‬\n       ‫اإلبــراء ال يكــون إال عــن حــق ســابق وإنــكار احلــق يقتضــي نفــى القضــاء‬\n                     ‫أو اإلبــراء منــه فيكــون مكذبــا لدعــواه وبينتــه فــا تســمع )‪.‬‬\n\n\n\n\n‫‪117‬‬\n\f‫ادعــى املدعــى بــأن املدعــى عليــه اقتــرض منــه قرضــه حســنه مبوجــب‬\n‫شــيك ولــم يســدد مــن هــذه القرضــة شــيئا ‪ ،‬طلــب إلــزام املدعــى عليــة‬\n‫بســداد القرضــة ‪ ،‬انكــر املدعــى عليــة القرضــة وذكــر بــأن املبلــغ‬\n‫مقابــل عــدة مشــاريع يف مجــال اإلنشــاء ‪ -‬أبــرز املدعــى عليــه ورقــة‬\n‫مخالصــة مت رصدهــا ‪ ،‬ذكــر املدعــى بــأن ورقــة املخالصــة صحيحــة‬\n‫وال تشــمل القرضــة ‪ ،‬حضــر احــد شــهود املخالصــة وشــهد علــى صحتهــا‬\n‫وأن املخالصــة بخصــوص إصالحــات يف فلتــن ميلكهــا املدعــى ولــم يتــم‬\n‫التعــرض للقــرض املدعــى بــه أثنــاء تدويــن املخالصــة ‪ ، .‬اقــر املدعــى‬\n‫عليــه وكالــة بصحــة شــهادة الشــاهد ‪ ،‬ودفــع بــأن هــذه املخالصــة‬\n‫ماحيــة لــكل عالقــة بــن الطرفــن مبــا يف ذلــك موضــوع القــرض ‪،‬‬\n‫ابــرز املدعــى وكالــة ســند القــرض ومت رصــده ورصــد شــيك القــرض‪،‬‬\n‫صــادق املدعــى عليــه علــى هــذا الســند ودفــع بــأن املدعــى أصالــة لــم‬\n‫يحــول ملوكلــه املبلــغ املذكــور والشــيك املذكــور ليــس قرضــا وإمنــا‬\n‫هــو شــراكة ‪ ،‬قــرر املدعــى وكالــة أنــه لــم يســتطع إحضــار شــاهد‬\n‫ســند القرضــة لوجــود خــاف بينــة وبــن موكلــه ‪ ،‬اكتفــى الطرفــان‬\n‫مبــا قدمــاه ‪ ،‬اســتدل القاضــي علــى مجموعــة قرائــن مت ذكرهــا أن‬\n‫املخالصــة املذكــورة ال تشــمل ســند القــرض املذكــور ‪ ، .‬حيــث أنكــر‬\n‫املدعــى عليــه القــرض ثــم ملــا قــدم املدعــى شــاهده قــرر أن مبلــغ القــرض‬\n‫داخــل يف التســوية وأن املخالصــة ماحيــة لــكل عالقــة بــن الطرفــن‬\n‫وملــا ذكــره الفقهــاء مــن أن مــن أنكــر احلــق ثــم ملــا قامــت البينــة ادعــى‬\n‫قضــاء أو إبــراء ســابقا إلنــكاره لــم يســمع منــه وان أتــى ببينــة لذلــك‬\n\n                                                                                       ‫‪118‬‬\n\f      ‫صــدر احلكــم بإلــزام املدعــى عليــه بــأن يدفــع للمدعــى مبلــغ القــرض‬\n      ‫املدعــى بــه ‪ ،‬اعتــرض املدعــى عليــه علــى احلكــم ‪ ،‬صــدق احلكــم مــن‬\n                                                         ‫محكمــة االســتئناف ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد‪:‬‬\n      ‫فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة مبحافظــة جــدة وبنــاء علــى‬\n      ‫املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة مبحافظــة‬\n      ‫جــدة ‪ /‬املســاعد برقــم ‪ 32601199‬وتاريــخ ‪1432/12/24‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 321618639‬وتاريــخ ‪1432/12/24‬ه ـ ففــي يــوم‬\n      ‫األحــد املوافــق ‪1433/04/04‬ه ـ حضــر ‪ ...‬ســعودي اجلنســية مبوجــب‬\n      ‫ا شــرعي ًا عــن املدعــي ‪ ...‬مبوجــب‬\n                                          ‫الســجل املدنــي رقــم ‪ ...‬بصفتــه وكيـ ً‬\n      ‫الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة شــمال محافظــة جــدة‬\n      ‫رقــم ‪ 94723‬وتاريــخ ‪1432/11/05‬ه ـ اجللــد ‪ 11140‬كمــا حضــر‬\n      ‫حلضــوره ‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...‬بصفتــه‬\n      ‫ا شــرعي ًا عــن املدعــى عليــه ‪ ...‬مبوجــب الوكالــة الصــادرة‬         ‫وكي ـ ً‬\n      ‫مــن كتابــة العــدل الثانيــة شــمال محافظــة جــدة رقــم ‪ 96361‬وتاريــخ‬\n      ‫ا يف دعــواه ‪ :‬إن املدعــى عليــه‬\n                                      ‫‪1430/11/09‬ه ـ اجللــد ‪ 9029‬وادعــى قائـ ً‬\n      ‫أصالــة اقتــرض مــن موكلــي مبلــغ وقــدره مائــة وخمســون ألــف ريــال‬\n      ‫قرضــة حســنة مبوجــب الشــيك املســحوب علــى البنــك ‪ ...‬برقــم ‪000001‬‬\n      ‫وتاريــخ ‪2011/01/25‬م وحــاول موكلــي عــدة مــرات مــع املدعــى عليــه‬\n      ‫أصالــة إلرجــاع املبلــغ إال أن املدعــى عليــه أصالــة مياطــل يف الســداد ومعي‬\n      ‫صــورة مــن توثيــق املدينويــة علــى املدعــى عليــه أصالــة باملبلــغ والشــيك‬\n‫‪119‬‬\n\f‫املــودع باســم املدعــى عليــه أصالــة املذكــور أعــاه أطلــب إلــزام املدعــى‬\n‫عليــه أصالــة بدفــع مبلــغ وقــدره مائــة وخمســون ألــف ريــال ملوكلــي‬\n‫هــذه دعــواي وبعــرض الدعــوى علــى املدعــى عليــه وكالــة قــال أطلــب‬\n‫اإلمهــال للــرد وصــورة مــن املســتندات هكــذا أجــاب وعليــه جــرى تســليم‬\n‫املدعــى عليــه وكالــة صــورة مــن الشــيك وصــورة مــن توثيــق مدينويــة‬\n‫علــى املدعــى عليــه أصالــة‪ .‬ويف يــوم الســبت املوافق‪1433/07/19‬ه ـ‬\n‫حضــر املدعــي وكالــة ‪ ...‬واملدونــه هويتــه ووكالتــه ســابقا وحضــر ‪...‬‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...‬بصفتــه وكيــا عــن‪...‬‬\n‫مبوجــب الوكالــة رقــم ‪ 39355‬وتاريــخ ‪1431/4/28‬ه ـ والصــادرة مــن‬\n‫كتابــة عــدل الثانيــة بجــدة وبســؤال املدعــى عليــه وكالــة عــن جوابــه‬\n‫قــال ان مــا ذكــره املدعــي وكالــة مــن أن موكلــه اقــرض موكلــي‬\n‫مبلــغ وقــدره مائــة وخمســون ألــف ريــال غيــر صحيــح وإمنــا املبلــغ كان‬\n‫مقابــل عمــل لعــدة مشــاريع يف مجــال اإلنشــاء هكــذا أجــاب وبســؤال‬\n‫املدعــى عليــه وكالــة عــن بينتــه عــن أن املبلــغ كان مقابــل عمــل لعــدة‬\n‫مشــاريع يف مجــال اإلنشــاء قــال ســأحضرها يف اجللســة القادمــة هكــذا‬\n‫قــال‪ .‬ويف يــوم الســبت املوافــق‪ 1434/01/03‬ه ـ لــدي أنــا ‪ ...‬القاضــي‬\n‫يف احملكمــة العامــة مبحافظــة جــدة وخلــف فضيلــة الشــيخ ‪ ...‬افتتحــت‬\n‫اجللســة وفيهــا حضــر املدعــي وكالــة‪ ...‬وحضــر املدعــى عليــه وكالــة‬\n‫‪ ...‬املثبــت حضورهمــا يف جلســة ســابقة وبســؤال املدعــي وكالــة عــن‬\n‫بينتــه أجــاب قائــا بينتــي ورقــة املخالصــة هكــذا أجــاب وابــرز ورقــة‬\n‫املخالصــة وهــذا نصهــا ( بعــد عــون اهلل تعالــى وتوفيقــه مت االجتمــاع‬\n‫بحضــور كل مــن الســيد ‪( ...‬املالــك) والســيد ‪ ...‬والســيد ‪( ...‬املقاولــن‬\n‫واملشــرفني علــى التنفيــذ) وذلــك بحضــور كل مــن‪ ...‬و‪ ...‬كمحكمــن‬\n\n\n                                                                                   ‫‪120‬‬\n\f      ‫ارتضاهــم الطرفــان ومت االتفــاق وهلل احلمــد واملنــة بــن الطرفــن علــى‬\n                                                                             ‫مــا يلــي‪:‬‬\n      ‫‪ -1‬حتــددت مســتحقات الطــرف الثانــي يف مشــروع ‪ ...‬مببلــغ مائتــان‬\n                                          ‫ألــف ريــال فقــط بشــكل قاطــع ونهائــي‬\n      ‫‪ -2‬حتــددت مســتحقات الطــرف الثانــي يف مشــروع ‪ ...‬مببلــغ مليــون‬\n                       ‫وأربعمائــة وواحــد وســبعون ألــف ومائــة وعشــرون ريــال‬\n      ‫‪ -3‬حتــددت مســتحقات الطــرف األول ملبالــغ اإلصالحــات ثمانيــة‬\n      ‫وعشــرون ألــف وخمســمائة وخمســة وخمســون ألــف ريــال وتكــون‬\n      ‫خالصــة احلســاب هــي مبلــغ إجمالــي وقــدره مليــون وأربعمائــة واثنــن‬\n      ‫وأربعــون ألــف وخمســمائة وخمســة وســتون ريــال وبعــد خصــم املبالــغ‬\n      ‫املســتلمة ســواء بشــيكات أو نقديــة أو حــواالت اصبــح املســتحق‬\n      ‫للطــرف الثانــي يف ذمــة الطــرف األول مبلــغ مائتــان وخمســون ألــف ريــال‬\n      ‫ال غيــر وذلــك يف جميــع جزئيــات وبنــود املوقعــن وقــد قــام الطــرف األول‬\n      ‫بتســديد الطــرف الثانــي املبلــغ املذكــور أعــاه مبوجب شــيك رقم‪0007‬‬\n      ‫صــادر مــن البنــك ‪ ...‬وبهــذا يبــرئ كل طــرف ذمــة اآلخــر وليــس ألي‬\n      ‫مــن الطرفــن حــق لــدى الطــرف اآلخــر حاليــا أو مســتقبال فيمــا يخــص‬\n      ‫املشــروعني أعــاه واهلل ولــي التوفيــق توقيــع الطــرف األول ( املالــك)‬\n                     ‫توقيــع الطــرف الثانــي توقيــع احملكمــن ‪ ...‬و‪ ...‬و‪ )...‬ا‪.‬ه ـ‬\n      ‫وبعــرض ذلــك علــى املدعــي وكالــة أجــاب قائــا هــذه املخالصــة‬\n      ‫صحيحــة لكــن املبلــغ املدعــى بــه خــارج هــذه املخالصــة واطلــب إلــزام‬\n      ‫املدعــى عليــه بســداد املبلــغ هكــذا أجــاب وبســؤاله عــن بينتــه يف ذلــك‬\n      ‫أجــاب قائــا نعــم لــدي بينــه واحضــر للشــهادة وادائهــا ‪ ......‬ســعودي‬\n      ‫اجلنســية مبوجــب الهويــة الوطنيــة رقــم ‪ ...‬وهــو مــن مواليــد عــام ‪1374‬ه ـ‬\n\n\n‫‪121‬‬\n\f‫وميلــك شــركة مقــاوالت ويعمــل بهــا وليــس لــه قرابــة بطــريف الدعــوى‬\n‫وبســؤاله عمــا لديــه شــهد قائــا ( أشــهد هلل كان بــن املدعــي أصالــة‬\n‫واملدعــى عليــه أصالــة نــزاع حــول فلتــن يف جــدة ميلكهمــا املدعــي‬\n‫أصالــة فدعانــي شــقيق املدعــي اصالــة للصلــح بينهمــا فأصلحــت‬\n‫بينهمــا يف هــذه الورقــة املرصــودة أعــاه بعــد الوقــوف علــى العقاريــن‬\n‫املذكوريــن وتقييــم اإلصالحــات ولــم نتعــرض أثنــاء كتابتنــا للورقــة‬\n‫املرصــودة أعــاه ملبلــغ القــرض البالــغ قــدره مئــة وخمســون ألــف ريــال‬\n‫ال مــن قريــب وال مــن بعيــد) هكــذا شــهد وبعــرض ذلــك علــى املدعــى‬\n‫عليــه وكالــة أجــاب قائــا أطلــب مهلــة لإلجابــة عنهــا هكــذا أجــاب‪.‬‬\n‫ويف يــوم الســبت املوافــق‪1434/05/04 :‬ه ـ حضــر املدعــي وكالــة‪:‬‬\n‫‪ ...‬واملدعــى عليــه وكالــة‪ ، ... :‬املثبــت حضورهمــا يف جلســة ســابقة‪،‬‬\n‫وبســؤال املدعــى عليــه وكالــة عمــا اســتمهل مــن أجلــه أجــاب قائــا‪:‬‬\n‫شــهادة الشــاهد صحيحــة مطابقــة للواقــع‪ ،‬وهــي تــدل علــى وجــود‬\n‫مخالصــة نهائيــة ماحيــة لــكل عالقــة بــن موكلــي واملدعــي أصالــة‬\n‫مبــا يف ذلــك موضــوع القــرض‪ ،‬وهــذه الشــهادة يف صاحلنــا‪ ،‬هكــذا‬\n‫أجــاب‪ .‬ثــم أبــرز املدعــي وكالــة ورقــة وجــرى اطالعنــا عليهــا وهــذا‬\n‫نصهــا‪( :‬توثيــق مديونيــة‪ ،‬مت االتفــاق بــن كل مــن الطــرف األول ‪...‬‬\n‫‪ ،‬والطــرف الثانــي‪ ، ... :‬علــى أن يقــوم الطــرف األول بتحويــل مبلــغ‪:‬‬\n‫مئــة وخمســن ألــف ريــال ســعودي إلــى الطــرف الثانــي بغــرض تســديد‬\n‫بعــض االلتزامــات اخلاصــة بالطــرف الثانــي‪ ،‬هــذا وســيقوم الطــرف‬\n‫الثانــي بتحريــر شــيك مؤجــل بتســديد هــذه املديونيــة‪ ،‬وعلــى ذلــك‬\n‫جــرى التوقيــع‪ .‬الطــرف األول‪ ... :‬توقيعــه بتاريــخ‪2011/1/24 :‬م ‪،‬‬\n‫الطــرف الثانــي‪ ... :‬توقيعــه بتاريــخ‪2001/1/24 :‬م شــاهد‪ ... :‬بــدون‬\n\n\n                                                                                ‫‪122‬‬\n\f      ‫توقيــع)‪ .‬ا‪ .‬ه ـ وبعــرض ذلــك علــى املدعــى عليــه وكالــة أجــاب قائــا‪:‬‬\n      ‫هــذه الورقــة املرصــودة أعــاه صحيحــة قــد وقعهــا موكلــي‪ ،‬ولكــن‬\n      ‫املدعــي أصالــة لــم يحــول ملوكلــي املبلــغ املذكــور‪ ،‬والشــيك املدعــى بــه‬\n      ‫ذا الرقــم‪ 000001 :‬يف‪2011/1/25 :‬م وقــدره‪ :‬مئــة وخمســون ألــف ريال‬\n      ‫ليــس قرضــا وإمنــا هــو شــركة ملــا قدمــت مــن بينــات‪ ،‬هكــذا أجــاب‪.‬‬\n      ‫وبســؤال املدعــى عليــه وكالــة عــن زيــادة بينــة أجــاب قائــا‪ :‬أكتفــي‬\n      ‫مبــا قدمــت‪ ،‬هكــذا أجــاب‪ .‬ونظــرا لوصــول القضيــة لهــذا احلــد أفهمــت‬\n      ‫املدعــي وكالــة بإحضــار الشــاهد الــوارد اســمه يف الورقــة املرصــودة‬\n      ‫أعــاه فقــرر قائــا‪ :‬ســوف أحضــره يف اجللســة القادمــة‪ ،‬هكــذا أجــاب‪.‬‬\n      ‫ويف يــوم األحــد املوافــق‪1434/10/11 :‬ه ـ حضــر املدعــي وكالــة ‪...‬‬\n      ‫واملدعــى عليــه وكالــة ‪ ...‬املثبــت حضورهمــا يف جلســة ســابقة وبســؤال‬\n      ‫املدعــي وكالــة عمــا اســتمهل مــن اجلــه أجــاب قائــا‪ :‬إن الشــاهد الــذي‬\n      ‫طلبــت املهلــة ألجــل إحضــاره بينــه وبــن موكلــي خــاف ولــم نتمكــن‬\n      ‫مــن إحضــاره هكــذا أجــاب‪ .‬ثــم قــرر طــريف النــزاع قائلــن‪ :‬نكتفــي‬\n      ‫مبــا قدمنــا ونطلــب البــت يف دعوانــا‪ ،‬هكــذا قــررا‪ .‬ويف يــوم األربعــاء‬\n      ‫املوافــق‪1434/10/14 :‬ه ـ حضــر‪ ... :‬ســعودي اجلنســية مبوجــب الهويــة‬\n      ‫الوطنيــة رقــم‪ ... :‬وحضــر حلضــوره‪ ...... :‬ســعودي اجلنســية مبوجــب الهويــة‬\n      ‫الوطنيــة رقــم‪ ... :‬وبعــرض الصلــح عليهمــا قــرر املدعــي قائــا‪ :‬ال أرغــب‬\n      ‫يف الصلــح‪ ،‬إن ســند توثيــق املديونيــة املرصــود يف جلســة ســابقة هــو‬\n      ‫إقــرار مــن املدعــى عليــه أصالــة باقتراضــه منــي‪ ،‬هكــذا قــرر‪ .‬وبســؤال‬\n      ‫طــريف النــزاع عــن الشــيك هــل كتــب عليــه قــرض أو شــراكة أجابــا‬\n      ‫قائلــن‪ :‬الشــيك لــم يكتــب عليــه ســبب املبلــغ ال قــرض وال شــراكة‬\n      ‫القضيــة وتأملهــا‪ ،‬وألن املدعــى عليــه وكالــة‬\n                                                   ‫ّ‬      ‫هكــذا قــررا‪ .‬وبدراســة‬\n\n\n‫‪123‬‬\n\f‫قــرر أن موكلــه اســتلم مبلغــا قــدره‪ :‬مئــة وخمســون ألــف ريــال ألجــل‬\n‫جتاريــة‪ ،‬وأنكــر كونهــا قرضــا‪ ،‬لــم يقـ ّـدم ّبينــة تؤيــد دفعــه‪،‬‬ ‫ّ‬      ‫شــراكة‬\n‫وغايــة مــا قــدم ورقــة املخالصــة املرصودة ســابقا واملتضمنة‪ :‬أن املســتحق‬\n‫للمدعــى عليــه ‪ ...‬يف ذمــة املدعــي ‪ ...‬ـ بعــد خصــم املبالــغ املســتلمة ســواء‬\n‫بشــيكات أو حــواالت أو نقــدا ـ مبلغــا قــدره‪ :‬مئتــان وخمســون ألــف ريــال‬\n                                                   ‫فيمــا يخــص املشــروعني‪ .‬ا‪ .‬ه ـ‬\n‫وقــد دفــع املدعــي وكالــة بــأن هــذه املخالصــة لــم يدْ ُخــل فيهــا القــرض‪،‬‬\n‫ودفعــه هــذا مؤيــد باآلتــي‪1 :‬ـ العبــارة املثبتــة على ورقــة املخالصة ونصها‪:‬‬\n‫(وبهــذا يبــرئ كل طــرف ذمــة اآلخــر ‪ . .‬فيمــا يخــص املشــروعني)‪،‬‬\n‫وهــذا يــدل علــى عــدم دخــول موضــوع القــرض يف املخالصــة‪2 .‬ـ شــهادة ‪...‬‬\n‫‪ ...‬والتــي صــادق علــى صحتهــا املدعــى عليــه وكالــة واملتضمنــة‪ :‬أنــه قــام‬\n‫بالصلــح بــن الطرفــن ولــم يتعــرض أثنــاء الصلــح ملبلــغ القــرض البالــغ‬\n‫قدمــه‬\n     ‫قــدره‪ :‬مئــة وخمســون ألــف ريــال‪ .‬يضــاف ملــا ســبق الســند الــذي ّ‬\n‫املدعــي وكالــة ـ وصــادق علــى صحتــه املدعــى عليــه وكالــة ـ املرصــود‬\n‫مديونيــة‪ ،‬مت االتفــاق بــن الطــرف‬  ‫ّ‬      ‫ســابقا ونــص احلاجــة منــه‪( :‬توثيــق‬\n‫األول‪ ، ... :‬والطــرف الثانــي‪ ...:‬أن يقــوم الطــرف األول بتحويــل مبلــغ‬\n‫قــدره‪ :‬مئــة وخمســون ألــف ريــال للطــرف الثانــي بغــرض تســديد الطــرف‬\n‫الثانــي االلتزامــات اخلاصــة بــه ‪ . .‬تاريــخ‪2011/1/24 :‬م) فقــد جــاء يف‬\n‫مديونيــة مبعنــى أنــه قــرض وقــدره‪ :‬مئــة وخمســون‬ ‫ّ‬       ‫هــذا الســند أن املبلــغ‬\n‫ألــف ريــال وكان تاريــخ الســند ‪2011/1/24‬م وحتريــر الشــيك كان‬\n‫بتاريــخ‪2011/1/25 :‬م والقاعــدة أن (األصــل نســبة احلــادث ألقــرب‬\n‫أوقاتــه)‪ ،‬فــدل أن املبلــغ محــل الدعــوى قرضــا ال شــراكة‪ .‬ويضــاف ـ‬\n‫أيضــا ـ أن املدعــى عليــه وكالــة أنكــر أن موكلــه قــد اقتــرض مــن‬\n\n\n                                                                                          ‫‪124‬‬\n\f      ‫املدعــي أصالــة ـ كمــا يف جوابــه علــى الدعــوى ـ‪ ،‬ثــم ملــا قـ ّـدم املدعــي‬\n      ‫وكالــة شــهادة الشــاهد ‪ ...‬قــرر أن مبلــغ القــرض داخــل يف التســوية‬\n      ‫وأن املخالصــة ماحيــة لــكل عالقــة بــن طــريف الدعــوى‪ ،‬وقــد ذكــر‬\n      ‫ـراء‬\n      ‫ـاء أو إبـ ً‬‫الفقهــاء فيمــن أنكــر احلــق ثـ ّـم ملّــا قامــت ّبينــة ا ّدعــى قضـ ً‬\n      ‫ســابق ًا إلنــكاره لــم يســمع منــه وإن أتــى ببينــة؛ ألنــه واحلــال مــا ُذكــر‬\n      ‫يكــون ادعائــه القضــاء واإلبــراء مكذب ـ ًا لدعــواه وبينتــه فــا تســمع‬\n      ‫منــه‪ ،‬قــال يف اإلقنــاع وشــرحه الكشــاف ‪( :341/6‬فأمــا إن أنكــره‬\n      ‫ثــم ثبــت فادعــى قضــاء أو إبــراء ســابقا إلنــكاره لــم يســمع منــه‪ ،‬وإن‬\n      ‫ببينــة نصـاً‪ ،‬فلــو ادعــى عليــه ألفـ ًا مــن قــرض‪ ،‬فقــال‪ :‬مــا اقترضــت‬  ‫أتــى ّ‬\n      ‫منــه شــيئا‪ ،‬أو مــن ثمــن مبيــع فقــال‪ :‬مــا ابتعــت منــه شــيئا‪ ،‬ثــم ثبــت‬\n      ‫أنــه اقتــرض أو اشــترى ببينــة أو إقــرار فقــال‪ :‬قضيتــه مــن قبــل هــذا‬\n      ‫الوقــت‪ ،‬أو أبرأنــي مــن قبــل هــذا الوقــت؛ لــم يقبــل منــه ولــو أقــام بــه‬\n      ‫بينــة؛ ألن القضــاء أو اإلبــراء ال يكــون إال عــن حــق ســابق‪ ،‬وإنــكار‬\n      ‫احلــق يقتضــي نفــي القضــاء أو اإلبــراء منــه‪ ،‬فيكــون مكذبــا لدعــواه‬\n      ‫وبينتــه فــا تســمع)‪ ،‬لذلــك كلــه فقــد أعلمـ ُـت املدعــى عليــه أصالــة‬\n      ‫بــأن لــه ميــن املدعــي أصالــة بهــذه الصيغــة‪( :‬أقســم بــاهلل العظيــم الــذي‬\n      ‫يعلــم خائنــة األعــن ومــا تخفــي الصــدور الواحــد الغالــب الطالــب‬\n      ‫الضــار النافــع الــذي يعلــم خائنــة األعــن ومــا تخفــي الصــدور أن املبلــغ‬\n      ‫املدعــى بــه وقــدره‪ :‬مئــة وخمســون ألــف ريــال قــرض أقرضتــه املدعــى‬\n      ‫عليــه أصالــة‪ ... :‬وليــس شــراكة جتاريــة‪ ،‬ولــم يدخــل موضــوع القــرض‬\n      ‫ـ محــل الدعــوى ـ يف املخالصــة املوقعــة بيننــا) فقــرر قائــا‪ :‬أرغــب يف‬\n      ‫ســماع ميــن املدعــي أصالــة بالصيغــة املذكــورة أعــاه‪ ،‬هكــذا قــرر‪.‬‬\n      ‫عنــد ذلــك عرضــت اليمــن علــى املدعــى بعــد تذكيــره بخطرهــا وبقولــه‬\n\n\n‫‪125‬‬\n\f‫صلــى اهلل عليــه وســلم (مــن حلــف علــى ميــن هــو فيهــا فاجــر ليقتطــع بهــا‬\n‫مــال امــرئ مســلم لقــي اهلل وهــو عليــه غضبــان) رواه مســلم فاســتعد‬\n‫لليمــن فأذنــت لــه فحلــف قائــا‪( :‬أقســم بــاهلل العظيــم الغالــب الطالــب‬\n‫الضــار النافــع الــذي يعلــم خائنــة األعــن ومــا تخفــي الصــدور أن املبلــغ‬\n‫املدعــى بــه وقــدره‪ :‬مئــة وخمســون ألــف ريــال قــرض أقرضتــه املدعــى‬\n‫عليــه أصالــة‪ ... :‬وليــس شــراكة جتاريــة‪ ،‬ولــم يدخــل موضــوع القــرض‬\n‫ـ محــل الدعــوى ـ يف املخالصــة املوقعــة بيننــا)‪ ،‬هكــذا حلــف ورضــي‬\n‫بذلــك املدعــى عليــه‪ .‬فبنــاء علــى مــا ســلف فقــد ثبــت لــدي أن املبلــغ ـ‬\n‫محــل النــزاع ـ قــرض ال شــراكة‪ ،‬وأمــرت املدعــى عليــه أصالــة‪ ... :‬أن‬\n‫يســلم للمدعــي أصالــة‪ ... :‬املبلــغ املدعــى بــه وقــدره‪ :‬مئــة وخمســون ألــف‬\n‫ريــال‪ ،‬وبذلــك قضيــت‪ .‬وبإعــان احلكــم عليهمــا قــرر املدعــي قناعتــه‬\n‫باحلكــم‪ ،‬أمــا املدعــى عليــه فقــرر عــدم قناعتــه واســتعد بتقــدمي الئحــة‬\n‫اعتراضيــة فجــرى تســليمه نســخة مــن احلكــم وأفهمتــه بــأن لــه احلــق يف‬\n‫تقــدمي اعتراضــه خــال مــدة أقصاهــا ثالثــن اعتبــارا مــن هــذا اليــوم‬\n‫وإذا لــم يقــدم الئحتــه خــال املــدة املقــررة ســقط حقــه يف االعتــراض‬\n‫القطعيــة‪ .‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا‬\n                                                    ‫ّ‬         ‫واكتســب احلكــم‬\n            ‫محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف‪1434/10/14 :‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد‪ ،‬ويف يــوم االحــد املوافــق‪1435/01/28 :‬ه ـ‬\n‫عــادت املعاملــة مــن محكمــة االســتئناف وبرفقهــا قــرار الدائــرة‬\n‫احلقوقيــة اخلامســة رقــم القــرار‪ 35111495 :‬يف‪1435/01/10 :‬ه ـ ونص‬\n‫احلاجــة منــه (وبدراســة احلكــم وصــورة ضبطــه والئحتــه االعتراضيــة‬\n‫تقــرر املوافقــة علــى احلكــم) ‪.‬ا‪.‬ه ـ وللبيــان جــرى اثباتــه وأمــرت بإحلــاق‬\n‫ذلــك علــى الصــك والســجل‪ .‬وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا‬\n\n\n                                                                                     ‫‪126‬‬\n\f                  ‫محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف‪1435/01/28 :‬ه ـ‬\n      ‫احلمــد هلل وحــده ‪ ،‬والصــاة والســام علــى رســول اهلل ‪ ،‬وبعــد‪ :‬فقــد‬\n      ‫جــرى م ّنــا نحــن قضــا َة االســتئناف بالدائــرة احلقوقيــة اخلامســة يف‬\n      ‫محكمــة االســتئناف مبنطقــة مكــة املكرمــة االطــا ُع علــى هــذا‬\n      ‫احلكــم الصــادر مــن فضيلــة الشــيخ ‪ ...‬القاضــي يف احملكمــة العامــة‬\n      ‫بجــدة املســجل بعــدد ‪ 34330175‬وتاريــخ ‪1434/10/14‬ه ـ املتضمــن‬\n      ‫دعــوى ‪ ...‬ضــد ‪ ...‬احملكــوم في ــه مبــا دون باطــن الصــك ‪ ،‬وبدراســة‬\n      ‫احلكــم وص ــورة ضبط ــه والئحتــه االعتراضيــة تقــرر املوافقــة علــى‬\n      ‫احلكــم‪ .‬وبــاهلل التوفيــق ‪ ،‬وصل ــى اهلل عل ــى نبينــا محمــد وعل ــى آل ــه‬\n                                                                  ‫وصحب ــه وســلم ‪.‬‬\n\n\n\n\n‫‪127‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"8772d0b1-3c0f-5928-9c22-98c49da1913e","source_page_start":117,"source_page_end":127,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"6741ce866d62429e1bf0b94656db830d4a9e828777c604bcd74afc36d7e6109b","normalized_text_hash":"90d582603c96129a3c485ffc2ac73cd26bd2dbd29c341a6569c13bf3447fa26e","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v4-p117-34330175"},{"id":"6d212a6d-5250-5e01-9f2d-582eef563d95","document_type":"judgment","category":"judicial","subcategory":"general","title":"قرض -رهن ذهب -رهن ذهب الزوجة لسداد دين زوجها املدعى عليه -سداد قيمة الذهب لفك الرهن -اإلفهام بحرمة هذا الرهن -القرض إذا زادت قيمته عن وقت القرض فاملعتبر قيمته وقت القرض -على اليد ما أخذت حتى تؤديه -إقرار املدعى عليه مبا ورد يف الدعوى -ال يجوز الرجوع فيما أقربه -إلزام املدعى عليه بسداد قيمة الذهب وقت القرض.","document_number":"331239103","case_number":"33439582","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باخلبر بن","circuit":"الدائرة احلقوقية الثانية يف محكمة الاستئناف رقم 34252233","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/22","year":"1434","subject":"قرض -رهن ذهب -رهن ذهب الزوجة لسداد دين زوجها املدعى عليه -سداد قيمة الذهب لفك الرهن -اإلفهام بحرمة هذا الرهن -القرض إذا زادت قيمته عن وقت القرض فاملعتبر قيمته وقت القرض -على اليد ما أخذت حتى تؤديه -إقرار املدعى عليه مبا ورد يف الدعوى -ال يجوز الرجوع فيما أقربه -إلزام املدعى عليه بسداد قيمة الذهب وقت القرض.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/5/22 :‬هـ‬\n                 ‫ُ‬                 ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪331239103 :‬‬\n                    ‫َر ْق ُم الدعوى‪33439582 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n      ‫‪/34252233‬ق‪/2‬أ تاريخه‪1434/6/26 :‬هـ‬\n\n\n\n ‫قــرض ‪ -‬رهــن ذهــب ‪ -‬رهــن ذهــب الزوجــة لســداد ديــن زوجهــا املدعــى‬\n ‫عليــه ‪ -‬ســداد قيمــة الذهــب لفــك الرهــن ‪ -‬اإلفهــام بحرمــة هــذا‬\n ‫الرهــن ‪ -‬القــرض إذا زادت قيمتــه عــن وقــت القــرض فاملعتبــر قيمتــه‬\n ‫وقــت القــرض ‪ -‬علــى اليــد مــا أخــذت حتــى تؤديــه ‪ -‬إقــرار املدعــى عليــه‬\n ‫مبــا ورد يف الدعــوى ‪ -‬ال يجــوز الرجــوع فيمــا أقربــه‪ -‬إلــزام املدعــى عليــه‬\n                                          ‫بســداد قيمــة الذهــب وقــت القــرض‪.‬‬\n\n\n\n\n      ‫‪ -1‬قوله صلى اهلل عليه وسلم ( على اليد ما أخذت حتى تؤديه ) ‪.‬‬\n ‫‪ -2‬قــرر الفقهــاء ـ رحمهــم اهلل ـ أن القــرض إذا زادت قيمتــه عــن وقــت‬\n ‫القــرض فاملعتبــر قيمتــه وقــت القــرض ‪ ،‬ألنــه هــو الوقــت الــذي لــزم‬\n                                                  ‫املقتــرض قيمتــه يف ذمتــه ‪.‬‬\n ‫‪ -3‬رجــوع املقــر عــن إقــراره ‪ ،‬ال يقبــل منــه يف قــول عامــة أهــل العلــم‬\n                             ‫كمــا حــكاه املوفــق ـ رحمــه اهلل ـ يف املغنــي ‪.‬‬\n ‫‪ -4‬فتــوى اللجنــة الدائمــة رقــم ( ‪ ) 22577‬يف ‪1434/2/17‬ه ـ ونــص‬\n ‫احلاجــة منــه ‪ ( :‬وبعــد دراســة اللجنــة لالســتفتاء أجابــت بــأن هــذه‬\n ‫املعاملــة املســؤول عنهــا غيــر جائــزة ‪ ،‬ألن حقيقتهــا بيــع نقــد بنقــد‬\n ‫أكثــر منــه إلــى أجــل ويف ذلــك جمــع بــن ربــا الفضــل وربــا النســيئة) ‪.‬‬\n                              ‫‪ -5‬املادة ( ‪ ) 55‬من نظام املرافعات الشرعية ‪.‬‬\n\n                                                                                      ‫‪128‬‬\n\f      ‫ادعــت املدعيــة علــى املدعــى عليــه أنهــا ســاعدته يف ســداد ديــن عليــه‬\n      ‫حيــث قامــت برهــن الذهــب الــذي لهــا لــدى محــل للذهــب مــن خــال بيــع‬\n      ‫صــوري يشــترط فيــه عــدم بيــع الذهــب حتــى يســدد املدعــى عليــه هــذا‬\n      ‫الديــن وذكــرت مكونــات الذهــب وقيمتــه ‪ .‬ولقــد مت إمهــال املدعــى‬\n      ‫عليــه أربعــة أشــهر لســدادها دون جــدوى حتــى تاريخــه ولــم يتــم فــك‬\n      ‫الرهــن حتــى اآلن‪ .‬طلبــت املدعيــة إلــزام املدعــى عليــه بســداد قيمــة‬\n      ‫الذهــب حتــى يتــم فــك رهــن واملســتحق عليــه هــو مبلــغ (‪)40.000‬ريــال‪،‬‬\n                           ‫والباقــي قــدره ‪228500‬ريــال فهــي يف ذمــة املدعيــة‪.‬‬\n      ‫قدمــت البينــة علــى دعواهــا فاتــورة الذهــب متضمنــة مــا ادعتــه‪ ،‬وأن‬\n      ‫مــدة الســداد كانــت أربعــة اشــهر ولكنهــا تعــدت إلــى ثمانيــة أشــهر‬\n      ‫حيــث لــم يحضــر املدعــى عليــه ولــم يــرد مبلغــه قــررت احملكمــة الســير‬\n      ‫يف الدعــوى أحضــرت املدعيــة بائــع الذهــب لســماع مــا لديــه وأكــد‬\n      ‫مــا أدعتــه املدعيــة مــن أقــوال‪ ، .‬يف جلســة أخــرى حضــرت املدعيــة‬\n      ‫وحضــر حلضورهــا املدعــى عليــه وجــرى ســؤاله عــن الدعــوى‪ .‬فــرد أنــه‬\n      ‫مــا ذكرتــه صحيــح وأنــه مســتعد بدفــع مــا تطلبــه املدعيــة‪ ،‬جــرى إفهــام‬\n      ‫الطرفــن أن مــا قامــا بــه غيــر جائــز شــرع ًا ‪ ،‬يف جلســة أخــرى حضــر‬\n      ‫املدعيــان واختلفــا يف قيمــة الذهــب وســعر الرهــن ‪ ،‬وقــام املدعــى عليــه‬\n      ‫بالتشــكيك يف قــول الشــاهد ومت ســؤاله عــن ســبب مصادقتــه لــكالم‬\n      ‫الشــاهد يف جلســة ســابقة فأجــاب مــرة أخــرى أن كالم الشــاهد غيــر‬\n                                  ‫صحيــح وأنــه لــم يســتلم منــه شــيئ ًا مــن املبلــغ ‪،‬‬\n      ‫ـاء علــى مــا تقــدم‪ :‬ومبــا أن مــا حصــل بــن الطرفــن مــع بائــع الذهــب‬      ‫بنـ ً‬\n\n‫‪129‬‬\n\f‫مــن رهــن الذهــب هــي معاملــة محرمــة كمــا قــرره أعضــاء اللجنــة‬\n‫الدائمــة ألنــه بيــع نقــد بنقــد أكثــر منــه إلــى أجــل ويف ذلــك جمــع بــن‬\n‫ربــا الفضــل وربــا النســيئة وحيــث إن مــا حصــل مــن البيــع هــو بيــع صحيــح‬\n‫مســتكمل شــروطه ‪ ،‬ومبــا أن املدعــى عليــه قــد أقــر بصحــة مــا جــاء يف‬\n‫دعــوى املدعيــة ‪ ،‬ويف شــهادة الشــاهد ورجــوع املدعــى عليــه عــن تصديقه‬\n‫لهــا وعــن تصديقــه يف شــهادة الشــاهد وهــو مــا ال يجــوز عنــد عامــه أهــل‬\n‫العلــم وألن علــى اليــد مــا أخــذت حتــى تؤديــه الزمــت احملكمــة املدعــى‬\n‫عليــه بدفــع مبلــغ (‪ )31000‬ريــال قيمــة الذهــب الــذي اقترضــه‪ ،‬وصــرف‬\n‫النظــر عمــا زاد مــن مبالــغ طلبتهــا املدعيــة ‪ .‬قنعــت املدعيــة ولــم يقنــع‬\n‫املدعــى عليــه ‪ ،‬صــدق علــى احلكــم مــن محكمــة االســتئناف باملنطقــة‬\n                                                                       ‫الشــرقية ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده أمــا بعــد فلــدي أنــا (‪ ).....‬القاضــي يف احملكمــة العامــة‬\n‫باخلبــر بنــاء علــى املعاملــة احملالــة إلينــا مــن فضيلــة الرئيــس املســاعد‬\n‫برقــم ‪ 33439582‬يف ‪1433/7/1‬ه ـ واملقيــدة بــوارد احملكمــة برقــم‬\n‫‪ 331239103‬يف ‪1433/7/1‬ه ـ عليــه افتتحــت اجللســة يف يــوم الســبت‬\n‫‪1433/8/24‬ه ـ الســاعة العاشــرة والنصــف وفيهــا حضــرت املدعيــة ‪...‬‬\n‫ســعودية بالســجل املدنــي رقــم ‪ ...‬ولــم يحضــر املدعــى عليــه ‪ ...‬وقد أفادت‬\n‫املدعيــة أنهــا كانــت قــد اســتعدت بتبليغــه وتعــذر عليهــا ذلــك فبنــاء‬\n‫علــى املــادة (‪ )55‬مــن نظــام املرافعــات الشــرعية فقــد قــررت رفــع اجللســة‬\n‫لتبليغــه ويف جلســة أخــرى حضــرت املدعيــة ‪ ...‬املثبتــة هويتهــا ســابقا ولــم‬\n\n\n                                                                                     ‫‪130‬‬\n\f      ‫يحضــر املدعــى عليــه ‪ ...‬ولــم يردنــا مــا يفيــد تبلغــه مــن عدمــه فبنــاء علــى‬\n      ‫املــادة (‪ )55‬مــن نظــام املرافعــات الشــرعية فقــد قــررت ســماع الدعــوى‬\n      ‫غيابيــا فادعــت املدعيــة قائلــة يف دعواهــا إننــي ســبق أن ســاعدت املدعــى‬\n      ‫عليــه الغائــب عــن مجلــس احلكــم زوجــي ‪ ...‬يف ســداد ديــن عليــه حيــث‬\n      ‫قمــت برهــن ذهبــي لــدى محــل ذهــب عــن طريــق بيــع صــوري اشــترط‬\n      ‫فيــه أال يبيــع صاحــب الذهــب هــذا الذهــب حتــى يســدد املدعــى عليــه‬\n      ‫هــذا الديــن وكان هــذا الذهــب مكونــا مــن كرســي وســت بناجــر‬\n      ‫واســوارتني أبيــض مــع أصفــر وسلســلة وتعليقــة وكــف وجــادة صغيــر‬\n      ‫وكان قيمتهــا اثنــن وســتني ألفــا وثمامنائــة وخمســن ريــاال وقــد أمهــل‬\n      ‫املدعــى عليــه أربعــة أشــهر لســدادها ولكنــه لــم يســددها حتــى تاريخــه‬\n      ‫ولــم نقــم بفــك الرهــن حتــى اآلن فأطلــب إلزامــه بســداد قيمــة الذهــب‬\n      ‫ألمتكــن مــن فــك رهنــي وقــدر املســتحق عليــه أربعــون ألــف ريــال وأمــا‬\n      ‫الباقــي وقــدره اثنــان وعشــرون ألفــا وثمامنائــة وخمســون ريــاال فهــي يف‬\n      ‫ذمتــي هكــذا ادعــت فطلبــت منهــا البينــة علــى دعواهــا فأبــرزت فاتــورة‬\n      ‫الذهــب الصــادرة مــن مجوهــرات‪ ...‬يف ‪1433/1/4‬ه ـ واملتضمنــة أن يف‬\n      ‫ذمــة املدعــو ‪ ...‬للمحــل املذكــور مبلــغ اثنــن وســتني ألفــا وثمامنائــة‬\n      ‫وخمســن ريــاال ومذيــل خلــف الفاتــورة مــا نصــه‪( :‬الرجــاء مــن األخ ‪...‬‬\n      ‫تســديد رهــان ذهــب ‪ ...‬كامــل بــدون تقســيط وذلك لتعــدي وقت الرهان‬\n      ‫مــن أربعــة أشــهر إلــى ثمانيــة أشــهر حيــث إن ‪ ...‬باعــت علــي الذهــب‬\n      ‫برضــى زوجهــا ‪ ...‬بــأن يقــوم بتســديد املبلــغ علــى أربعــة أشــهر فقــط ولــم‬\n      ‫يحضــر ولــم يقــم بالتبريــر لعــدم تســديده أو عــدم حضــوره وشــكرا ‪...‬‬\n      ‫)انتهــى مضمونــه وحيــث إن املدعــى عليــه لــم يحضــر فقــد قــررت رفــع‬\n      ‫اجللســة لتبليغــه ويف جلســة أخــرى حضــرت املدعيــة املثبتــة هويتهــا ســابقا‬\n\n\n‫‪131‬‬\n\f‫ولــم يحضــر املدعــى عليــه وقــد كتــب خطــاب لتبليغــه ولــم يردنــا مــا‬\n‫يفيــد تبلغــه مــن عدمــه وقــد قــررت االســتمرار بالســير يف الدعــوى وقــد‬\n‫قــررت املدعيــة أنهــا أحضــرت بائــع الذهــب وترغــب ســماع مــا لديــه وقــد‬\n‫حضــر يف هــذه اجللســة املدعــو ‪ ) ...( ...‬وقــرر قائــا إن املدعيــة وزوجهــا‬\n‫الغائــب ‪ ...‬قــد حضــرا لــدي يف محــل الذهــب مجوهــرات ‪ ...‬يف الثقبــة‬\n‫قبــل قرابــة ســنة وكان املدعــى عليــه محتاجــا ملبلــغ مــن املــال فباعــت‬\n‫علــي املدعيــة الذهــب الــذي لديهــا بقرابــة ‪ 31‬ألــف ريــال ومت تســليم‬\n‫زوجهــا مبلــغ واحــد وثالثــن ألــف ريــال وقــد مت رهــن الذهــب لــدي علــى‬\n‫أن يفــك الــزوج الرهــن خــال أربعــة أشــهر وقــد اتفــق الطرفــان علــى ذلــك‬\n‫وقــد مضــت املــدة ولــم يتــم فــك الرهــن حتــى تاريخــه علمــا أن الذهــب‬\n‫املوجــود لــدي لــو أرادوا اشــتراءه فــإن قيمتــه تســاوي أربعــن ألــف ريــال‬\n‫تقريبــا هكــذا قــرر وحيــث إن املدعــى عليــه لــم يحضــر ولــم يردنــا مــا‬\n                   ‫يفيــد تبلغــه مــن عدمــه فقــد قــررت رفــع اجللســة لتبليغــه‪.‬‬\n‫ويف جلســة أخــرى حضــرت املدعيــة ‪ ...‬املثبتــة هويتهــا ســابق ًا وحضــر‬\n‫معهــا املدعــى عليــه ‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n‫‪ ...‬فجــرى ســؤال املدعــى عليــه عــن دعــوى املدعيــة املضبوطــة يف اجللســة‬\n‫املاضيــة فقــال مــا ذكرتــه املدعيــة يف دعواهــا صحيــح وال مطعــن لــي‬\n‫فيــه وأنــا مســتعد بدفــع مــا تطلبــه املدعيــة هكــذا أجــاب فجــرى ســؤال‬\n‫املدعيــة عــن طلبهــا فقالــت أطلــب أن يســدد املدعــى عليــه لبائــع الذهــب‬\n‫قيمــة الذهــب لكــي أســترد ذهبــي مــن البائــع فجــرى إفهــام الطرفــن‬\n‫بــأن العمليــة التــي قامــوا بهــا غيــر جائــزة شــرع ًا كمــا نصــت عليــه فتــوى‬\n‫اللجنــة الدائمــة وجــرى ســؤال املدعية هل تطلــب الذهب أو قيمته فقالت‬\n‫أطلــب قيمــة الذهــب هكــذا أجابــت ويف جلســة أخــرى حضــر الطرفــان‬\n\n\n                                                                                        ‫‪132‬‬\n\f      ‫وقــد جــرى تأمــل أوراق املعاملــة وجــرى ســؤال الطرفــن عــن املبلــغ الــذي‬\n      ‫مت بيــع الذهــب بــه يف ذلــك الوقــت فأجابــت املدعيــة بــأن قيمتــه كانــت‬\n      ‫قرابــة ‪ 43‬ألــف ريــال وأجــاب املدعــى عليــه بأنــه ليــس يف ذمتــه شــيء‬\n      ‫للمدعيــة وأن الــذي تفــاوض مــع راعــي الذهــب واســتلم املبلغ هــي املدعية‬\n      ‫وهــو حضــر معهــا كمحــرم علمــا أن املبلــغ الــذي اســتلمته قــدره ثمانيــة‬\n      ‫وعشــرون ألفــا وخمســمائة ريــال هكــذا أجــاب فجــرى إفهــام الطرفــن‬\n      ‫بــأن بائــع الذهــب ســبق وأن حضــر فقــال إن قيمــة الذهــب الــذي اشــتراه‬\n      ‫منهــم يف ذلــك الوقــت يســاوي واحــدا وثالثــن ألــف ريــال ‪ ،‬فأجابــت‬\n      ‫املدعيــة قائلــة أصــادق علــى هــذا علمــا أنــه لــم يتــم احتســاب ســعر الرهــن‬\n      ‫وأجــاب املدعــى عليــه قائــا مــا ورد يف كالم الشــاهد غيــر صحيــح‬\n      ‫هكــذا أجــاب فجــرى ســؤاله ملــاذا صــادق علــى كالم الشــاهد ملــا تلــي‬\n      ‫عليــه يف اجللســة التــي حضرهــا يف ‪1434/01/24‬ه ـ فأجــاب مــرة أخرى‬\n      ‫بــأن مــا ورد يف كالم الشــاهد غيــر صحيــح وأنــا لــم أســتلم منــه شــيئا‬\n      ‫مــن املبلــغ هكــذا أجــاب ‪ ،‬فجــرى تأمــل أوراق املعاملــة فبنــاء علــى مــا‬\n      ‫تقــدم وبعــد ســماع الدعــوى واإلجابــة ومبــا أن مــا حصــل بــن الطرفــن‬\n      ‫مــع بائــع الذهــب مــن رهــن للذهــب فهــي معاملــة محرمــة كمــا قــرره‬\n      ‫أعضــاء اللجنــة الدائمــة يف الفتــوى رقــم ( ‪ )22577‬يف ‪1423/02/17‬ه ـ‬\n      ‫ونــص احلاجــة مــن الفتــوى ‪ (:‬وبعــد دراســة اللجنــة لالســتفتاء أجابــت بــأن‬\n      ‫هــذه املعاملــة املســؤول عنهــا غيــر جائــزة ألن حقيقتهــا بيــع نقــد بنقــد‬\n      ‫أكثــر منــه إلــى أجــل ويف ذلــك جمــع بــن ربــا الفضــل وربــا النســيئة ‪).....‬‬\n      ‫إلــخ ‪ ،‬وحيــث إن مــا حصــل مــن البيــع الســابق للرهــن فهــو بيــع صحيــح‬\n      ‫مســتكمل الشــروط ‪ ،‬وحقيقــة مــا حصــل مــن املدعيــة أنهــا أقرضــت‬\n      ‫املدعــى عليــه الذهــب ثــم باعــه علــى بائــع الذهــب بواحــد وثالثــن ألــف‬\n\n\n‫‪133‬‬\n\f‫ريــال وهــو قيمتــه يف وقــت القــرض ‪ ،‬وقــد قــرر الفقهــاء رحمهــم اهلل‬\n‫أن القــرض إذا زادت قيمتــه عــن وقــت القــرض فاملعتبــر قيمتــه وقــت‬\n‫القــرض ألنــه هــو الوقــت الــذي لزمــت املقتــرض قيمتــه يف ذمتــه ومبــا‬\n‫أن املدعــى عليــه قــد أقــر بصحــة مــا جــاء يف دعــوى املدعيــة ويف شــهادة‬\n‫الشــاهد يف اجللســة املعقــودة يف ‪ ، 01 /24‬ثــم رجــع عــن تصديقــه لهــا‬\n‫وعــن تصديقــه ملــا جــاء يف شــهادة الشــاهد ‪ ،‬وهــذا الرجــوع ال يقبــل منــه‬\n‫يف قــول عامــة أهــل العلــم كمــا حــكاه املوفــق رحمــه اهلل يف املغنــي‬\n‫وألن (علــى اليــد مــا أخــذت حتــى تؤديــه) ولــكل مــا ســبق فقــد ألزمــت‬\n‫املدعــى عليــه ‪ ...‬بــأن يدفــع للمدعيــة ‪ ...‬مبلــغ واحــد وثالثــن ألــف ريــال‬\n‫قيمــة الذهــب الــذي اقترضــه منهــا وقــت القــرض يف ‪1433/01/04‬ه ـ‬\n‫وصرفــت النظــر عــن مطالبــة املدعيــة باملبلــغ الزائــد عــن قيمــة الذهــب‬\n‫وقــت القــرض وقــدره تســعة آالف ريــال وبــه حكمــت وبعرضــه علــى‬\n‫الطرفــن قــررت املدعيــة قناعتهــا باحلكــم وقــرر املدعــى عليــه عــدم‬\n‫القناعــة باحلكــم وطلــب رفعــه حملكمــة االســتئناف بالئحــة اعتراضيــة‬\n‫فأجيــب لطلبــه وأفهــم مبقتضــى تعليمــات االســتئناف ‪ .‬وبــاهلل التوفيــق‬\n‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                             ‫‪ 1434/04/10‬ه ـ‬\n‫احلمــد هلل وحــده أمــا بعــد فقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n‫بخطــاب رئيســها رقــم ‪ 341314104‬يف ‪1434/6/27‬ه ـ وبرفقــه قــرار‬\n‫الدائــرة احلقوقيــة الثانيــة يف محكمــة االســتئناف رقــم ‪34252233‬‬\n‫يف ‪1434/6/26‬ه ـ املظهــر بــه علــى صــك احلكــم ونصــه (احلمــد هلل‬\n‫وحــده وبعــد فقــد اطلعنــا علــى هــذا الصــك رقــم ‪ 34186328‬وتاريــخ‬\n‫‪1434/4/13‬ه ـ الصــادر مــن فضيلــة القاضــي ‪ ...‬وأصدرنــا القــرار رقــم‬\n\n\n                                                                                     ‫‪134‬‬\n\f      ‫‪/34252233‬ق‪/2‬أ وتاريــخ ‪1434/6/26‬ه ـ املتضمــن املصادقــة علــى‬\n      ‫احلكــم) قاضــي اســتئناف ‪ ...‬قاضــي اســتئناف ‪ ...‬رئيــس الدائــرة ‪...‬‬\n      ‫أختامهــم وتوقيعاتهــم وحــرر لئــا يخفــى يف ‪1434/7/11‬ه ـ وصلــى اهلل‬\n                                                            ‫وســلم علــى نبينــا محمــد‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة احلقوقيــة‬\n      ‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة املقيــدة‬\n      ‫لــدى احملكمــة برقــم ‪ 341314104‬وتاريــخ ‪1434/ 5/29‬ه ـ الــواردة‬\n      ‫مــن فضيلــة رئيــس احملكمــة العامــة مبحافظــة اخلبــر املســاعد برقــم‬\n      ‫‪ 331239103‬وتاريــخ ‪1434/5/22‬ه ـ املرفــق بهــا الصــك الصــادر مــن‬\n      ‫فضيلــة القاضــي باحملكمــة الشــيخ‪ .../‬املســجل برقــم ‪34186328‬‬\n      ‫وتاريــخ ‪1434/4/13‬ه ـ بشــأن دعــوى‪ .../‬ضــد‪ .../‬يف قضيــة حقوقيــة‬\n      ‫وقــد تضمــن الصــك حكــم فضيلــة القاضــي مبــا هــو مــدون ومفصــل‬\n      ‫فيــه ‪ .‬وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق‬\n      ‫املعاملــة قررنــا املصادقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى‬\n                    ‫نبينــا محمــد وآلــه وصحبــه وســلم حــرر يف‪1434/6/26‬ه ـ ‪.‬‬\n\n\n\n\n‫‪135‬‬\n\f136\n\f137\n\f138\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"8772d0b1-3c0f-5928-9c22-98c49da1913e","source_page_start":128,"source_page_end":138,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"b0146d37332e35ab5a05b069f380a7c5d5823a7958aa07aed5a748e5554b1769","normalized_text_hash":"e52cc682c89f9c5f0a21f7534ebe73d7ff8c3cba68a3cfbcfeedd7cfd85f01a5","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v4-p128-331239103"},{"id":"7fb118c7-35f1-5059-a160-7bf91ce278f8","document_type":"judgment","category":"judicial","subcategory":"general","title":"إعسار -مطالبة بإثبات إعسار عن سداد مال مختلس-الديون املترتبة على أفعال مجرمة ال ينظر يف اإلعسار بها -رد دعوى","document_number":"33204799","case_number":"7213","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالدمام","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/4/21","year":"1434","subject":"إعسار -مطالبة بإثبات إعسار عن سداد مال مختلس-الديون املترتبة على أفعال مجرمة ال ينظر يف اإلعسار بها -رد دعوى","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1433/4/21 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪33204799 :‬‬\n                              ‫َر ْق ُم الدعوى‪7213 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34197112‬تاريخه‪1434/4/24 :‬هـ‬\n\n\n      ‫إعســار‪ -‬مطالبــة بإثبــات إعســار عــن ســداد مــال مختلس‪-‬الديــون‬\n      ‫املترتبــة علــى أفعــال مجرمــة ال ينظــر يف اإلعســار بهــا ‪ -‬رد دعــوى‬\n                                                                   ‫اإلعســار‪.‬‬\n\n\n\n\n               ‫‪ -1‬التعميم الوزاري رقم ‪/4‬ض‪ 21795/‬يف‪1402/09/17‬هـ‪.‬‬\n      ‫‪ -2‬خطــاب رئيــس مجلــس القضــاء األعلــى رقــم ‪ 1/ 4074‬يف‬\n                                                ‫‪1429 /08 /04‬هــ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي بــأن يف ذمتــه للمدعــى عليــه املبلــغ املذكــور يف دعــواه‬\n      ‫وذلــك عــن قيمــة بضائــع وقــد ألــزم بســدادها له فعجز عن ذلــك وأودع يف‬\n      ‫الســجن‪ ،‬ولــذا طلــب إثبــات إعســاره واحلكــم بإنظــاره إلــى ميســرة‪،‬أقر‬\n      ‫املدعــى عليــه مبــا جــاء يف الدعــوى إال أنــه لــم يوافــق علــى إثبــات إعســار‬\n      ‫املدعــي ألن املبلــغ الــذي بذمتــه لــه كبيــر ولــم يبــن مصيــره‪ ،‬املدعــي‬\n      ‫أديــن يف احلــق العــام بخيانتــه لألمانــة واختالســه للمبالــغ التــي ألــزم‬\n      ‫بهــا يف احلــق اخلــاص والديــون املترتبــة علــى أفعــال مجرمــة ال ينظــر يف‬\n      ‫اإلعســار بهــا‪ ،‬قضــت احملكمــة بصــرف النظــر عــن دعــوى املدعــي‬\n      ‫بطلــب إعســاره‪ ،‬قنــع املدعــى عليــه باحلكــم وعــارض عليــه املدعــي‪،‬‬\n\n‫‪139‬‬\n\f                   ‫قــررت محكمــة االســتئناف املصادقــة علــى احلكــم ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ ).....‬القاضــي يف احملكمــة العامــة‬\n‫بالدمــام وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بالدمــام برقــم ‪ 7213‬وتاريــخ ‪1431/08/27‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 3125388‬وتاريــخ ‪1431/8/27‬ه ـ ففــي يــوم الثالثــاء‬\n‫املوافــق ‪1433/04/13‬ه ـ افتتحــت اجللســة الســاعة ‪ 10 : 22‬وفيهــا‬\n‫حضــر ‪ .....‬اردنــي اجلنســية مبوجــب اإلقامــة رقــم ‪ .....‬وحضــر حلضــوره‬\n‫‪ .....‬ســعودي بالســجل رقــم ‪ .....‬وبســؤال املدعــي عــن دعــواه قــال ان يف‬\n‫ذمتــي للمدعــى عليــه ‪ .....‬مبلــغ اربعــة عشــر مليــون وثمامنائــة وثمانيــة‬\n‫عشــر الــف وثالثمائــة وثالثــة وعشــرون ريــال وواحــد وســبعون هللــه‬\n‫وذلــك عــن قيمــة بضائــع وذلــك ثابــت مبوجــب الصــك الصــادر مــن هــذه‬\n‫احملكمــة برقــم ‪ 4/20‬يف ‪1428/02/21‬ه ـ وقــد عجــزت عــن الســداد‬\n‫واودعــت يف الســجن بتاريــخ ‪2006/04/20‬م كمــا صــدر بحقــي حكــم‬\n‫مــن احملكمــة اجلزائيــة بالدمــام برقــم ‪ 4/158‬يف ‪1427/11/05‬ه ـ‬\n‫يتضمــن ســجني ملــدة خمــس ســنوات مــن تاريــخ التوقيــف علــى ذمــة هــذه‬\n‫القضيــة مــع العلــم اننــي مــا ازال ســجني بهــذا املبلــغ حتــى االن واطلــب‬\n‫اثبــات اعســاري واحلكــم بإنظــاري إلــى ميســره هــذه دعــواي وبعــرض‬\n‫ا أن لــي بذمــة هــذا احلاضــر‬  ‫الدعــوى علــى املدعــى عليــه اجــاب قائ ـ ً‬\n‫مبلــغ اربعــة عشــر مليــون وثمامنائــة وثمانيــة عشــر الــف وثالثمائــة وثالثــة‬\n‫وعشــرون ريــال وواحــد وســبعون هللــه ولــم يســددني مــن هــذا املبلــغ‬\n‫شــيء وال اوافــق علــى اعســاره الن املبلــغ الــذي بذمتــه كبيــر ولــم يبــن‬\n\n                                                                                      ‫‪140‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"8772d0b1-3c0f-5928-9c22-98c49da1913e","source_page_start":139,"source_page_end":140,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"ad850947f74c39b939bd172cdfe891e58fa3555e44b569f5c89017c5ef301b47","normalized_text_hash":"9176ab2b87af35f351daa335aaa50c19eb53d7f25ee7d4d440ab65b2751ef925","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v4-p139-33204799"},{"id":"5e5c1cad-ec81-5acb-95ec-1460335f0126","document_type":"judgment","category":"judicial","subcategory":"general","title":"إعسار -صدور حكم بإلزام املدعى بدفع مبلغ مالي لصاحب مؤسسة -املطالبة بإثبات اإلعسار -عدم موافقة الدائن على إثبات اإلعسار بحجة أن مبلغ اإلعسار نتيجة اختاس -إثبات اإلعسار باليمن -قبول أداء اليمن من غير مسلم -عدم ثبوت ماءة املدين- ثبوت اإلعسار واإلفراج عن املدين ووجوب سداد املبلغ احملكوم به","document_number":"347286","case_number":"32412071","judgment_number":null,"decision_number":null,"circular_number":null,"court":null,"circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/10","year":"1434","subject":"إعسار -صدور حكم بإلزام املدعى بدفع مبلغ مالي لصاحب مؤسسة -املطالبة بإثبات اإلعسار -عدم موافقة الدائن على إثبات اإلعسار بحجة أن مبلغ اإلعسار نتيجة اختاس -إثبات اإلعسار باليمن -قبول أداء اليمن من غير مسلم -عدم ثبوت ماءة املدين- ثبوت اإلعسار واإلفراج عن املدين ووجوب سداد املبلغ احملكوم به","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫تاريخه‪1434/1/10 :‬هـ‬\n                        ‫ُ‬                ‫َر ْق ُم َّ‬\n                             ‫الص ِّك‪347286 :‬‬\n                          ‫َر ْق ُم الدعوى‪32412071 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                 ‫‪ 34178584‬تاريخه‪1434/4/3 :‬هـ‬\n\n\n      ‫إعســار‪ -‬صــدور حكــم بإلــزام املدعــى بدفــع مبلــغ مالــي لصاحــب‬\n      ‫مؤسســة‪ -‬املطالبــة بإثبــات اإلعســار‪ -‬عــدم موافقــة الدائــن علــى إثبــات‬\n      ‫اإلعســار بحجــة أن مبلــغ اإلعســار نتيجــة اختــاس‪ -‬إثبــات اإلعســار‬\n      ‫باليمــن‪ -‬قبــول أداء اليمــن مــن غيــر مســلم‪ -‬عدم ثبوت مــاءة املدين‪-‬‬\n      ‫ثبــوت اإلعســار واإلفــراج عــن املديــن ووجــوب ســداد املبلــغ احملكــوم بــه‬\n                                                                      ‫حــن ميســرة ‪.‬‬\n\n\n\n\n                                    ‫‪ -1‬املادة (‪ )231‬من نظام املرافعات الشرعية‪.‬‬\n         ‫‪ -2‬املادة (‪ )12/231‬من نظام املرافعات الشرعية والئحته التنفيذية‪.‬‬\n         ‫‪ -3‬املادة (‪ )11/231‬من نظام املرافعات الشرعية والئحته التنفيذية‪.‬‬\n      ‫‪ -4‬قولــه تعالــى‪( :‬وإن كان ذو عســرة فنظــرة إلــى ميســرة) ســورة البقــرة‬\n                                                                        ‫آية (‪.)280‬‬\n      ‫‪ -5‬قولــه صلــى اهلل عليــه وســلم لغرمــاء الــذي كثــر دينــه‪( :‬خــذوا مــا‬\n              ‫وجــدمت ليــس لكــم إال ذلــك) رواه مســلم وأبــو داود والترمــذي‪.‬‬\n      ‫‪ -6‬مــا ذهــب إليــه جمهــور العلمــاء مــن احلنفيــة والشــافعية واحلنابلــة‪:‬‬\n      ‫مــن أن الديــن إذا لــزم الشــخص بغيــر اختيــاره كقيمــة متلــف وأرش‬\n      ‫جنابة خطأ ونحوها فإن القول يف اإلعســار قول املدين بيمينه‪ .‬انظر‪:‬‬\n           ‫رد املختــار (‪ )384/5‬ومغنــى احملتــاج (‪ )155/2‬واإلنصــاف (‪.)242/13‬‬\n\n‫‪145‬‬\n\f‫ادعــى مقيــم جتــاه وكيــل صاحــب مؤسســة جتاريــة أنــه ســبق أن صــدر‬\n‫عليــه حكــم بإلزامــه بدفــع مبلــغ مائــة وســبعة عشــر ألــف ريــال لصاحــب‬\n‫املؤسســة وقــرر أنــه عاجــز عــن ســداد هــذا املبلــغ وطلــب إثبــات إعســاره‬\n‫جتــاه دائنــة‪ ،‬قــرر وكيــل الدائــن عــدم موافقتــه علــى إثبــات إعســار‬\n‫املدعــى ألن املبلــغ نــاجت عــن اختــاس‪ -‬جــرى االستفســار عــن أرصــدة‬\n‫وحــواالت واحملافــظ االســتثمارية ملدعــي اإلعســار فــورد اجلــواب بعــدم‬\n‫وجــود شــيء مــن ذلــك ملدعــي اإلعســار‪ ،‬طلبــت احملكمــة مــن جهــات‬\n‫التنفيــذ البحــث عــن أمــوال مدعــي اإلعســار الثابتــة واملنقولــة‪ ،‬جــرت‬\n‫مخاطبــة وزارة اخلارجيــة ملخاطبــة ســفارة بــاد مدعــي اإلعســار لإلفــادة‬\n‫عــن أموالــه يف بــاده ‪-‬لــم تــرد اإلفــادة‪ -‬جــرى الرجــوع إلــى القــرار‬\n‫الشــرعي املتضمــن توجــه الشــبهة القويــة للمدعــى عليه (مدعي اإلعســار‬\n‫يف هــذه القضيــة) باختــاس لفــة نحــاس وتعزيــره بالســجن واجللد‪،‬جــرى‬\n‫االطــاع علــى الصــك الشــرعي املصــدق مــن محكمــة االســتئناف‬\n‫املتضمــن إلــزام املدعــى عليــه (مدعــي اإلعســار يف هــذه القضيــة) بدفــع‬\n‫مائــة وســبعة عشــر ألــف ريــال للدائــن (املدعــى عليــه يف هــذه القضيــة)‬\n‫وقــد تضمنــت حيثيــات احلكــم أن أقــل أحــوال املدعــى عليــه أنــه فــرط‬\n‫فيمــا أؤمتــن عليــه‪ ،‬جــرى ســؤال وكيــل الدائــن هــل يعلــم أمــوا ًال ملدعــي‬\n‫اإلعســار فقــرر أنــه ال يعلــم عــن أمــوال مدعــي اإلعســار‪ ،‬لطــول ســجن‬\n‫مدعــي اإلعســار حيــث مضــى علــى ســجنه خمــس ســنوات تقريب ـ ًا لــذا‬\n‫جــرى ســؤاله عــن البينــة علــى صحــة دعــواه‪ ،‬قــرر مدعــي اإلعســار أنــه‬\n‫ال بينــة لديــه ألنــه ال يعرفــه أحــد ًا يف هــذه البــاد‪ ،‬جــرى ســؤال مدعــي‬\n\n                                                                                     ‫‪146‬‬\n\f      ‫اإلعســار عــن ديانتــه فقــرر أن ديانتــه البوذيــة‪ُ ،‬طلــب منــه اليمــن فحلــف‬\n      ‫بــاهلل العظيــم أنــه فقيــر معســر وال ميلــك مــا ًال ثابتـ ًا أو منقــو ًال هنــا أو يف‬\n      ‫بلــده ليســدد بــه الديــن وال شــيئ ًا منــه‪ ،‬بنــاء علــى مــا ذكــره القاضــي‬\n      ‫مــن حيثيــات وأدلــة وملــا قــرره أهــل العلــم مــن أن الديــن إذا لــزم شــخص‬\n      ‫بغيــر اختيــاره فالقــول قولــه يف اإلعســار بيمينــه لــذا صــدر احلكــم‬\n      ‫بإثبــات إعســاره واإلفــراج عنــه بعــد اكتســاب احلكــم القطعيــة وأن‬\n      ‫عليــه ســداد املبلــغ احملكــوم بــه للدائــن حلــن ميســرة‪ ،‬اعتــرض وكيــل‬\n                               ‫الدائن‪،‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬رئيــس احملكمــة اجلزائيــة مبحافظــة‬\n      ‫القطيــف وبنــاء علــى املعاملــة احملالــة لنــا برقــم ‪ 32412071‬وتاريــخ‬\n      ‫‪1432/09/15‬ه ـ املقيــدة باحملكمــة برقــم ‪ 321195590‬وتاريــخ‬\n      ‫‪1432/09/15‬ه ـ ففــي يــوم الثالثــاء املوافــق ‪1432/10/29‬ه ـ افتتحــت‬\n      ‫اجللســة وقــد حضــر ‪ ...‬ســريالنكي اجلنســية حامــل جــواز ســفر رقــم‬\n      ‫(‪ )...‬يف ‪2006/8/14‬م صــادر مــن كوملبــو كمــا حضــر ‪ ...‬ســعودي‬\n      ‫رقــم ســجله املدنــي (‪ )...‬بصفتــه وكيــل الشــرعي عــن ‪ ...‬مؤسســة‬\n      ‫‪ ...‬للنقــل والتخليــص اجلمركــي مبوجــب الوكالــة الصــادرة برقــم(‬\n      ‫‪) 546‬يف ‪1430/5/28‬ه ـ املخولــة لــه املرافعــة واملدافعــة كمــا حضــر‬\n      ‫ا ســبق‬ ‫املترجــم ‪ ...‬حامــل رخصــة إقامــة رقــم(‪ ) ...‬وادعــى االول قائ ـ ً‬\n      ‫ان صــدر علــي صــك شــرعي رقــم (‪/1/13‬ح ) يف ‪1432/5/1‬ه ـ مــن‬\n      ‫هــذه احملكمــة املتضمــن احلكــم علــي بدفــع مائــة وســبعة عشــر ألــف‬\n      ‫(‪ )117000‬ريــال لـ‪...‬صاحــب مؤسســة ‪ ...‬وأنــا معســر ال أســتطيع دفــع‬\n‫‪147‬‬\n\f‫هــذا املبلــغ وال شــيئا منــه أطلــب اثبــات إعســاري هــذه دعــواي وبعــرض‬\n‫الدعــوى علــى وكيــل الدائــن قــال أن موكلــي ال يوافــق علــى إثبــات‬\n‫إعســار املدعــى عليــه حيــث أن املبلــغ املدعــى بــه نــاجت عــن اختــاس‬\n‫وصــدر بذلــك قــرار شــرعي مــن هــذه احملكمــة يديــن املدعــى عليــه‬\n‫وبعــرض ذلــك علــى املدعــي قــال ال أســتطيع دفــع املبلــغ ونظــر ًا لعــدم‬\n‫ورود مــا يفيــد البحــث عــن أمــوال املدعــى فقــد قــررت االســتمرار يف‬\n‫إيقافــه ملــدة شــهرين ويف جلســة أخــرى بتاريــخ ‪1433/1/1‬ه ـ حضــر‬\n‫املدعــي ووكيــل الدائــن وســبق أن كتبنــا لالستفســار عــن حســابات‬\n‫املدعــى واحملافــظ االســتثمارية فوردنــا كتــاب رئيــس مجلــس هيئــة‬\n‫الســوق املاليــة رقــم ‪ 5513/6‬يف ‪1432/12/3‬ه ـ املتضمــن عــدم وجــود‬\n‫أي بيانــات اســتثمارية للمذكــور كمــا وردنــا خطــاب مديــر مؤسســة‬\n‫النقــد بالدمــام رقــم ‪22/7835‬ش‪ 3780/‬يف ‪1432/12/19‬ه ـ املتضمــن‬\n‫أنــه ال توجــد أي أرصــدت أو حســابات للمذكــور لــدى جميــع البنــوك‬\n‫واملصــارف العاملــة باململكــة ونظــر ًا لعــدم اســتكمال جهــات التنفيــذ‬\n‫البحــث والتحــري عــن مدعــي اإلعســار حســب النظــام وحســب خطابنــا‬\n‫لهــم برقــم ‪ 321436032‬يف ‪1432/11/12‬ه ـ فقــد قــررت اســتمرار يف‬\n‫إيقاف املدعى ملدة ثالثة أشــهر ويف جلســة أخرى بتاريخ ‪1433/4/3‬هـ‬\n‫لــدي أنــا ‪ ...‬القاضــي باحملكمــة اجلزائيــة مبحافظــة القطيــف والقائــم‬\n‫بعمــل فضيلــة رئيــس احملكمــة مبوجــب قــرار التكليــف رقــم ‪ 6160‬يف‬\n‫‪1433/3/30‬ه ـ حضــر مدعــي اإلعســار كمــا حضــر ‪ ...‬حامــل الســجل‬\n‫املدنــي رقــم (‪ )...‬بالوكالــة عــن ‪ ...‬صاحــب مؤسســة ‪ ...........‬مبوجــب‬\n‫الوكالــة الصــادرة مــن كاتــب العــدل يف الغرفــة التجاريــة والصناعيــة‬\n‫بالدمــام برقــم( ‪) 332‬يف ‪1428/6/3‬ه ـ ونظــر ًا لعــدم اســتكمال جهــات‬\n\n\n                                                                                 ‫‪148‬‬\n\f      ‫التنفيــذ البحــث والتحــري عــن مدعــي اإلعســار فقــد قــررت االســتمرار‬\n      ‫يف إيقــاف املدعــى عليــه مــدة شــهرين ويف جلســة أخــرى لــدي أنــا ‪...‬‬\n      ‫بتاريخ‪1433/06/03‬ه ـ حضــر املدعــي كمــا حضــر وكيــل الدائــن ‪...‬‬\n      ‫وقــد وردنــا خطــاب ســعادة مديــر ســجن القطيــف رقــم ‪3/21/4645/9‬‬\n      ‫يف ‪1433/6/3‬ه ـ املتضمــن أنــه متــت الكتابــة جلهــة االختصــاص للبحــث‬\n      ‫عــن أحوالــه املاديــة ولــم تردنــا اإلفــادة حتــى تاريخــه كمــا قــرر مدعــي‬\n      ‫االعســار أنــه عاجــز عــن الســداد وطلــب وكيــل الدائــن االســتمرار‬\n      ‫يف ســجنه عليــه فقــد قــررت االســتمرار يف إيقافــه مــدة ثالثــة أشــهر‬\n      ‫وســيتم إبــاغ مديــر الســجن ملتابعــة البحــث عــن أمــوال املدعــى عليــه ويف‬\n      ‫جلســة أخــرى بتاريخ‪1433/09/03‬ه ـ حضــر املدعــي ‪ ...‬كمــا حضــر‬\n      ‫‪ ...‬بالوكالــة عــن ‪ ...‬صاحــب مؤسســة ‪ ...‬للنقــل والتخليــص اجلمركــي‬\n      ‫ولــم تــرد إفــادة بخصــوص أمــوال املدعــى عليــه فجــرى ســؤال وكيــل‬\n      ‫الدائــن عــن علمــه بــأي أمــوال ملدعــي اإلعســار قــال ال أعلــم عــن أموالــه‬\n      ‫وبتصفــح املعاملــة جــرى االطــاع علــى الصــك الشــرعي الصــادر مــن‬\n      ‫هــذه احملكمــة برقــم ‪/1/13‬ح يف‪1432/5/1‬ه ـ املصــدق مــن محكمــة‬\n      ‫االســتئناف واملتضمــن احلكــم علــى املدعــى عليــه ‪ ...‬بدفــع مائــة وســبعة‬\n      ‫عشــر ألــف ريــال للدائــن ‪ ...‬بصفتــه صاحب مؤسســة ‪ ...‬للنقــل والتخليص‬\n      ‫اجلمركــي وقــد تضمنــت حيثيــات احلكــم أن أقــل أحــوال املدعــى عليــه‬\n      ‫أنــه فــرط فيمــا أؤمتــن عليــه كمــا جــرى االطــاع علــى القــرار الشــرعي‬\n      ‫رقم‪/1/261‬م‪20‬يف‪1432/7/3‬ه ـ الصــادر مــن هــذه احملكمــة‬\n      ‫املتضمــن توجــه الشــبهة القويــة علــى املدعــى عليــه ‪ ...‬باختــاس لفــة‬\n      ‫نحــاس وتعزيــره بســجنه ثــاث ســنوات وعشــرة أشــهر وجلــده ألــف‬\n      ‫وخمســمائة جلــدة ونظــر ًا لتأخــر ورود إفــادة اجلهــات االداريــة املعنيــة عــن‬\n\n\n‫‪149‬‬\n\f‫ا مبــا‬‫أمــوال مدعــي اإلعســار فقــد قــررت الكتابــة لهــم لإلفــادة عاج ـ ً‬\n‫لديهــم عــن أي أمــوال أو حتويــات ماليــة ملدعــي اإلعســار كمــا قــررت‬\n                        ‫االســتمرار يف إيقافــه حتــى موعــد اجللســة القادمــة‪.‬‬\n‫ويف جلســة أخــرى بتاريخ‪1433/11/21‬ه ـ حضــر مدعــي اإلعســار ‪...‬‬\n‫كمــا حضــر ‪ ...‬بصفتــه الوكيــل عــن الدائــن ‪ ...‬صاحــب مؤسســة ‪...‬‬\n‫للنقــل والتخليــص اجلمركــي وكنــا قــد كتبنــا لســعادة مديــر ســجن‬\n‫محافظــة القطيــف بكتابنــا رقــم ‪ 331660135‬يف ‪1433/9/5‬ه ـ‬\n‫بســرعة اإلفــادة عــن نتيجــة البحــث والتحــري فوردنــا كتابــه رقــم‬\n‫‪ 3/21/7588/9‬يف ‪1433/9/20‬ه ـ املتضمــن أنــه مت رفــع أوراقــه‬\n‫لســعادة وكيــل وزارة اخلارجيــة للشــؤون القنصليــة حيــال مخاطبــة‬\n‫ســفارة بــاده للبحــث والتحــري عــن أموالــه وممتلكاتــه يف بــاده‬\n‫مبوجــب كتــاب ســعادة وكيــل إمــارة املنطقــة الشــرقية رقــم ‪61827‬‬\n‫يف ‪1432/12/24‬ه ـ ولــم تردنــا اإلفــادة حتــى تاريخــه أ‪.‬ه ـ كمــا‬\n‫كتبنــا لســعادة مديــر مؤسســة النقــد بكتابنــا رقــم ‪331750166‬‬\n‫يف ‪1433/9/24‬ه ـ لإلفــادة عــن أي حتويــات ماليــة للمدعــي خــال‬\n‫الفتــرة ‪1427/10/17‬ه ـ وحتــى ‪1433/12/30‬ه ـ ولــم تردنــا إفــادة حتــى‬\n‫تاريخــه ونظــر ًا لذلــك ولعــدم حضــور املترجــم رغــم طلبــه فقــد قــررت‬\n‫األمــر باالســتمرار يف إيقــاف املدعــي مــدة ثالثــن يومــا ويف جلســة أخــرى‬\n‫بتاريخ‪1433/12/21‬ه ـ حضــر مدعــي االعســار ‪ ...‬ولــم يحضــر املترجــم‬\n‫رغــم طلبــه عــدة مــرات كمــا هــو موضــح يف احملضــر املرفــق باملعاملــة‬\n‫وقــد وردنــا كتــاب مديــر فــرع مؤسســة النقــد العربــي يف الدمــام رقــم‬\n‫‪ 33-4904‬يف ‪1433/12/1‬ه ـ املتضمــن أن املؤسســة قامــت بالتعميــم‬\n‫علــى البنــوك واملصــارف العاملــة باململكــة بخصــوص املوضــوع أعــاه‬\n\n\n                                                                                   ‫‪150‬‬\n\f      ‫وتلقــت كافــة اجاباتــه ومفادهــا عــدم وجــود حــواالت ماليــة تخــص‬\n      ‫املذكــور خــال الفتــرة املشــار إليهــا فســألت مدعــي االعســار ألديــه‬\n      ‫بينــة علــى إعســاره ففهــم الســؤال وقــال ال بينــة لــدي وال يعرفنــي يف هــذه‬\n      ‫البــاد أحــد ويف جلســة أخــرى بتاريخ‪1434/01/10‬ه ـ حضــر مدعــي‬\n      ‫االعســار ‪ ...‬كمــا حضــر وكيــل الدائــن ‪ ...‬وبســؤال املدعــي عــن ديانتــه‬\n      ‫بواســطة املترجــم ‪ ...‬ســيريالنكي اجلنســية ويحمــل إقامــة رقم(‪)...‬قــال‬\n      ‫إنــه بــوذي الديانــة فأفهمتــه بتوجــه اليمــن عليــه أنــه معســر ال ميلــك‬\n      ‫مــاال ثابت ـ ًا أو منقــو ًال فاضــا عــن حاجاتــه األساســية فاســتعد بذلــك‬\n      ‫ا مبــا ترجمتــه واهلل العظيــم أننــي فقيــر معســر ال أملــك مــا ًال‬\n                                                                            ‫وحلــف قائـ ً‬\n      ‫ثابت ـ ًا أو منقــو ًال هنــا أو يف بلــدي أســدد بــه الديــن الــذي علــي لــ‪ ...‬وال‬\n      ‫شــيئ ًا منــه هكــذا حلــف ‪ .‬فبنــاء علــى مــا تقــدم و حيــث تتلخــص دعــوى‬\n      ‫املقيــم ‪ ...‬بطلــب إثبــات إعســاره يف مواجهــة غرميــه ‪...‬والختصاصنــا‬\n      ‫بنظــر هــذه الدعــوى بنــاء علــى املــادة رقــم (‪ )231‬مــن نظــام املرافعــات‬\n      ‫الشــرعية ولوائحهــا التنفيذيــة وحيــث مت البحــث والتحــري عــن أمــوال‬\n      ‫مدعــي اإلعســار وفــق االجــراءات النظاميــة املنصــوص عليهــا يف املــادة‬\n      ‫(‪ )12/231‬مــن اللوائــح التنفيذيــة لنظــام املرافعــات الشــرعية ولــم يظهــر‬\n      ‫للمحكمــة وجــود أمــوال ملدعــي اإلعســار كمــا مت حبــس مدعــي‬\n      ‫اإلعســار اســتظهار ًا حلالــة وفــق املــادة (‪ )11/231‬مــن اللوائــح التنفيذيــة‬\n      ‫لنظــام املرافعــات الشــرعية مــدة تربــو علــى الســنة ونظــر ًا إلقــرار الدائــن‬\n      ‫أنــه ال يعلــم أي أمــوال للمديــن مدعــي اإلعســار وإلقــرار مدعــي االعســار‬\n      ‫عجــزه عــن إحضــار البينــة ألنــه غريــب ال يعرفــه أحــد كمــا أنــه ســجني‬\n      ‫منــذ خمــس ســنوات تقريبــا كمــا هــو موضــح يف املعاملــة ولقولــه تعالــى‬\n      ‫«وإن كان ذو عســرة فنظــرة إلــى ميســرة» البقــرة ‪ 280:‬ولقولــه صلــى‬\n\n\n‫‪151‬‬\n\f‫اهلل عليــه وســلم لغرمــاء الــذي كثــر دينــه (خــذوا مــا وجــدمت ليــس لكــم‬\n‫إال ذلــك ) رواه مســلم وابــوداود والترمــذي ونظــر ًا لعــدم ثبــوت مــاءة‬\n‫املديــن املذكــور قبــل واقعــة حبســه حيــث إنــه حضــر للمملكــة للعمــل‬\n‫ســائق ســيارة نقــل والغالــب علــى مثلــه عــدم املــاءة وألن الديــن املطالــب‬\n‫بــه لــم يثبــت أنــه مقابــل معاوضــة ماليــة ولــم يلزمــه مبوجــب عقــد متفــق‬\n‫عليــه كمــا أنــه لــم تثبــت إدانتــه باختــاس هــذا املبلــغ وإمنــا توجهــت عليــه‬\n‫الشــبهة القويــة بذلــك وحكــم عليــه يف احلــق اخلــاص لتفريطــه يف حفــظ‬\n‫مــا أمتــن عليــه كمــا هــو موضــح يف القــرار والصــك الشــرعي املشــار لهما‬\n‫يف جلســة ســابقة وملــا ذهــب إليــه جمهــور العلمــاء مــن احلنفيــة والشــافعية‬\n‫واحلنابلــة انظــر رد املختــار (‪ )384/5‬مغنــى احملتــاج (‪ )155/2‬اإلنصــاف‬\n‫(‪ )242/13‬مــن أن الديــن إذا لــزم الشــخص بغيــر اختيــاره كقيمــة‬\n‫متلــف وأرش جنايــة خطــأ ونحوهــا فــإن القــول يف اإلعســار قــول املديــن‬\n‫بيمينــه فــإذا حلــف أنــه معســر أخلــى ســبيله ولبــذل مدعــي اإلعســار‬\n‫اليمــن املذكــور فقــد ثبــت لــدي إعســار ‪ ...‬يف مواجهــة غرميــه ‪ ...‬وأمــرت‬\n‫باإلفــراج عنــه بعــد اكتســاب احلكــم القطعيــة وأفهمتــه بأن عليه ســداد‬\n‫املبلــغ احملكــوم بــه وقــدره مائــة وســبعة عشــر ألــف ريــال ســعودي للدائــن‬\n‫‪ ...‬حــن ميســرته وبإعــان احلكــم قــرر وكيــل الدائــن اعتراضــه وجــرى‬\n‫إفهامــه مراجعــة احملكمــة غــد ًا الســتالم نســخة احلكــم وأن لــه مهلــة‬\n‫ثالثــون ميـ ًا لتقــدمي اعتراضــه ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                                                  ‫وصحبــه وســلم ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬رئيــس احملكمــة اجلزائيــة مبحافظــة‬\n‫القطيــف فقــد انتهــت املهلــة املقــررة نظامـ ًا لتقــدمي االعتــراض دون تقــدمي‬\n‫املعتــرض أو مــن ميثلــه اعتراضــه عليــه فقــد اكتســب احلكــم القطعيــة‬\n\n\n                                                                                         ‫‪152‬‬\n\f      ‫بنــاء علــى املادة(‪)178‬مــن نظــام املرافعــات الشــرعية وللبيــان حــرر يف‬\n      ‫‪1434/2/16‬ه ـ ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                                                 ‫وســلم ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...‬رئيــس احملكمــة اجلزائيــة مبحافظــة‬\n      ‫القطيــف فقــد عــادت املعاملــة مــن محكمــة االســتئناف باملنطقــة‬\n      ‫الشــرقية وبرفقهــا القــرار رقــم ‪ 34178584‬يف ‪1434/4/3‬ه ـ املتضمــن‬\n                     ‫املصادقــة علــى احلكــم و للبيــان أحلــق يف ‪1434/4/13‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى رســولنا محمــد وآلــه وصحبــه‬\n      ‫أمــا بعــد ‪ ........‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة احلقوقيــة األولــى يف‬\n      ‫محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة مــن‬\n      ‫فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة القطيــف الشــيخ‪.........../‬‬\n      ‫برقــم ‪ 331039200‬وتاريــخ ‪1434/2/17‬ه ـ واملقيــدة لــدى احملكمــة‬\n      ‫برقــم ‪ 34/457423‬وتاريــخ ‪1434/2/24‬ه ـ املرفــق بهــا الصــك الصــادر‬\n      ‫مــن فضيلتــه املسـ ّـجل برقــم ‪ 347286‬وتاريــخ ‪1434/1/10‬ه ـ اخلــاص‬\n      ‫بدعوى‪( ... /‬ســرالنكي اجلنســية) ضد ‪ ........‬مؤسســة ‪ ...........‬يف قضية‬\n      ‫حقوقيــة وقــد تضمــن الصــك حكــم فضيلتــه مبــا هــو مــدون ومفصــل‬\n      ‫قررنــا املصادقــة‬ ‫فيــه ‪ .‬وبدراســة الصــك وصــورة ضبطــه وأوراق املعاملــة ّ‬\n       ‫علــى احلكــم ‪ ،‬ولبيانــه حــرر يف ‪1434/4/2‬هــ‪ ،‬واهلل ولــي التوفيــق ‪.‬‬\n\n\n\n\n‫‪153‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"8772d0b1-3c0f-5928-9c22-98c49da1913e","source_page_start":145,"source_page_end":153,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"71088e8922d0c80db4cacdc29dce61b85fc4beb862f67e31222df3e43db5b1e4","normalized_text_hash":"3bb7898a6ef1b0346ee5bed80237912180ec32d5ae246aab0212f917a1931127","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v4-p145-347286"}]$archive_payload$::jsonb AS data)
INSERT INTO public.legal_documents (
  id,document_type,category,subcategory,title,document_number,case_number,judgment_number,decision_number,
  circular_number,court,circuit,issuing_authority,document_date,hijri_date,year,subject,summary,facts,claims,
  reasoning,ruling,principle_text,full_text,legal_articles,source_id,source_file_id,source_page_start,
  source_page_end,original_source,acquisition_source,source_url,content_hash,normalized_text_hash,status,review_status
)
SELECT (x->>'id')::uuid,x->>'document_type',x->>'category',x->>'subcategory',x->>'title',x->>'document_number',
       x->>'case_number',x->>'judgment_number',x->>'decision_number',x->>'circular_number',x->>'court',x->>'circuit',
       x->>'issuing_authority',(x->>'document_date')::date,x->>'hijri_date',x->>'year',x->>'subject',x->>'summary',
       x->>'facts',x->>'claims',x->>'reasoning',x->>'ruling',x->>'principle_text',x->>'full_text',
       COALESCE(x->'legal_articles','[]'::jsonb),(x->>'source_id')::uuid,(x->>'source_file_id')::uuid,
       (x->>'source_page_start')::integer,(x->>'source_page_end')::integer,x->>'original_source',
       x->>'acquisition_source',x->>'source_url',x->>'content_hash',x->>'normalized_text_hash',x->>'status',x->>'review_status'
FROM payload CROSS JOIN LATERAL jsonb_array_elements(payload.data) AS x
LIMIT 25
ON CONFLICT (id) DO NOTHING;

